343	export async function renameFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
344	  const user = await requireUser();
345	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
346	  if (!row) return { error: "You don't have a free server." };
347	
348	  const name = String(formData.get("name") ?? "").trim().slice(0, 40);
349	  if (!name) return { error: "Enter a name." };
350	
351	  // Cosmetic only — never touches the container, the subdomain, or mc-router.
352	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { name } });
353	  revalidatePath("/dashboard/free-minecraft");
354	  return {};
355	}
