443	export async function sendFreeMinecraftCommand(_prev: unknown, formData: FormData): Promise<{ error?: string; response?: string }> {
444	  const user = await requireUser();
445	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
446	  if (!row) return { error: "You don't have a free server." };
447	
448	  const rl = checkRateLimit(`freemc:rcon:${user.id}`, { max: 20, windowMs: 60_000 });
449	  if (!rl.ok) return { error: `Too many commands — try again in ${rl.retryAfterSec}s.` };
450	
451	  const parsed = validateRconCommand(String(formData.get("command") ?? ""));
452	  if (!parsed.ok) return { error: parsed.error };
453	
454	  try {
455	    const host = await freemcHost();
456	    const result = await withServerSsh(host, (conn) => sendRcon(conn, row.containerName, user.id, parsed.command));
457	    if (!result.ok) return { error: result.error || "Server is asleep — connect first to wake it up." };
458	    return { response: result.response };
459	  } catch (e) {
460	    console.error("[free-minecraft] rcon command failed:", e);
461	    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
462	  }
463	}
