465	export async function getFreeMinecraftPlayers() {
466	  const user = await requireUser();
467	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
468	  if (!row) return { ok: false as const, error: "You don't have a free server." };
469	
470	  try {
471	    const host = await freemcHost();
472	    return await withServerSsh(host, (conn) => getFreeServerPlayers(conn, row.containerName, user.id));
473	  } catch {
474	    return { ok: false as const, error: "Server is asleep." };
