478	/** Current server.properties values, shaped for the shared MINECRAFT schema
479	 *  (lib/game-config.ts) — same field defs/types/options the paid game panel's
480	 *  Settings tab uses, just applied through Docker instead of a VM job. */
481	export async function getFreeMinecraftSettings() {
482	  const user = await requireUser();
483	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
484	  if (!row) return null;
485	
486	  const schema = schemaFor("minecraft");
