import { requireUser } from "@/lib/auth";
import { PortalHero } from "@/components/portal/PortalHero";
import { FreeMinecraftTabContent } from "@/components/customer/freemc/FreeMinecraftTabContent";

export const dynamic = "force-dynamic";

// Kept alive as its own route — the marketing site, the public server
// directory, and the per-server page all deep-link straight here. The nav
// entry that used to point at this page has moved: it's now the "Free
// Minecraft" tab on /dashboard/games (see FreeMinecraftTabContent, shared
// by both).
export default async function FreeMinecraftPage() {
  await requireUser();

  return (
    <div className="space-y-6">
      {/* The hero is passed IN rather than rendered here, so it appears only on
          the create path. Once a server exists its own dashboard hero names it,
          and two headers stacked on one screen is exactly the clutter the rest
          of this rebuild removed. */}
      <FreeMinecraftTabContent
        heroSlot={
          <PortalHero
            variant="games"
            title="Free Minecraft server"
            sub="One free Minecraft server per account. It sleeps when nobody's playing and wakes up the moment someone connects."
          />
        }
      />
    </div>
  );
}
import { getSetting, getSettingBool } from "@/lib/settings";
import { getFreeMinecraftDashboard, getFreeMinecraftSettings } from "@/lib/actions-free-minecraft";
import { FREEMC_PRESETS, FREEMC_GAME_TYPES, FREEMC_GAME_MODES } from "@/lib/free-minecraft-control";
import { FreeMinecraftCreateForm } from "@/components/customer/FreeMinecraftPanel";
import { FreeMcDashboard } from "@/components/customer/freemc/FreeMcDashboard";

/**
 * The actual free-Minecraft panel content (create form or full dashboard),
 * with no hero/heading of its own so it drops into any page. Shared between
 * /dashboard/free-minecraft (kept alive for existing deep links from the
 * marketing site and the public server directory — never remove that route)
 * and the "Free Minecraft" tab on /dashboard/games.
 */
/* Whether this content brings its own identity header.
   The dashboard's hero (components/customer/freemc/v2/FreeMcHero.tsx) already
   names the server, shows its address and carries the power controls, so a page
   that also renders a generic "Free Minecraft server" hero above it stacks two
   headers on one screen. The host asks for `heroSlot` and puts its own hero
   there only when there is no server yet — where a page-level header is exactly
   right, because the create form has no identity of its own. */
export async function FreeMinecraftTabContent({
  heroSlot,
}: {
  heroSlot?: React.ReactNode;
} = {}) {
  const [enabled, domain, dashboard] = await Promise.all([
    getSettingBool("free_minecraft_enabled", false),
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    getFreeMinecraftDashboard(),
  ]);

  const settings = dashboard ? await getFreeMinecraftSettings() : null;

  if (!enabled) {
    return (
      <div className="card max-w-md text-sm text-slate-400">
        Free servers aren&apos;t open yet — check back soon.
      </div>
    );
  }

  if (dashboard && settings) {
    return (
      <FreeMcDashboard
        server={dashboard}
        domain={domain}
        schemaFields={settings.schema.fields}
        properties={settings.properties}
        presets={FREEMC_PRESETS}
        gameTypes={FREEMC_GAME_TYPES}
        gameModes={FREEMC_GAME_MODES}
      />
    );
  }

  return (
    <>
      {heroSlot}
      <FreeMinecraftCreateForm
        domain={domain}
        gameTypes={FREEMC_GAME_TYPES}
        gameModes={FREEMC_GAME_MODES}
        showPreview
      />
    </>
  );
}
"use server";

/**
 * ADMIN-only actions for the free Minecraft product — a separate surface from
 * lib/actions-free-minecraft.ts (the customer-facing actions, which all resolve
 * "the caller's own server" via `requireUser()` + `userId`). Admins need to
 * operate on ANY server by id, so every export here re-checks `requireArea("fleet")`
 * itself (never trust the UI alone) and looks the row up by `id`, not by caller.
 *
 * `"use server"` means every export is a network-reachable endpoint.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";
import { withServerSsh, exec, shellQuote } from "./ssh-exec";
import { getFreeServerStatus, FREEMC_GAME_TYPES } from "./free-minecraft-control";
import { getFreemcHostCapacity, FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB } from "./freemc-capacity";
import type { SftpServer } from "./sftp";

type Result = { ok?: boolean; error?: string };

/** Same dedicated Docker host lib/actions-free-minecraft.ts talks to — a real
 *  Server row (hostname="freemc-host"), not a customer VPS. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

/** Lazy, on-demand live status for one server (running + player count) — the
 *  list page deliberately does NOT fetch this for every row on load (see
 *  app/admin/free-minecraft/page.tsx's header note); this backs a per-row
 *  "check status" button instead. */
export async function adminGetFreeMinecraftStatus(
  id: string
): Promise<{ ok: true; running: boolean; players: { online: number; max: number } | null } | { ok: false; error: string }> {
  await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { containerName: true } });
  if (!row) return { ok: false, error: "Server not found." };

  try {
    const host = await freemcHost();
    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
    return { ok: true, running: status.running, players: status.players };
  } catch (e) {
    console.error("[admin-freemc] status check failed:", e);
    return { ok: false, error: "Could not reach the free Minecraft host." };
  }
}

/**
 * Force a server's public listing off — a moderation lever for a listing that
 * needs to be pulled (abuse report, inappropriate tagline/description, etc.)
 * without deleting the server or touching its container.
 */
export async function adminUnpublishFreeMinecraftServer(id: string): Promise<Result> {
  const admin = await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({ where: { id }, select: { id: true, isPublic: true } });
  if (!row) return { error: "Server not found." };
  if (!row.isPublic) return { ok: true };

  await db.freeMinecraftServer.update({ where: { id }, data: { isPublic: false } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.freemc_unpublish", detail: id },
  });
  revalidatePath("/admin/free-minecraft");
  return { ok: true };
}

/**
 * Delete a stray/abandoned free server: `docker rm -f` its container + wipe its
 * data dir on freemc-host, then remove the DB row. Same cleanup shape as the
 * customer-facing `deleteFreeMinecraftServer` in lib/actions-free-minecraft.ts,
 * but admin-gated and looked up by `id` (any server), not by the caller's own
 * userId. The DB row is removed even if the SSH cleanup fails — a stuck row
 * that no longer resolves to a real container is worse than an orphaned
 * container directory an admin can still clean up by hand.
 */
export async function adminDeleteFreeMinecraftServer(id: string): Promise<Result> {
  const admin = await requireArea("fleet");
  const row = await db.freeMinecraftServer.findUnique({
    where: { id },
    select: { id: true, containerName: true, subdomain: true },
  });
  if (!row) return { error: "Server not found." };

  try {
    const host = await freemcHost();
    await withServerSsh(host, async (conn) => {
      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
    });
  } catch (e) {
    console.error("[admin-freemc] delete cleanup failed (row is removed regardless):", e);
  }

  await db.freeMinecraftServer.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.freemc_delete", detail: `${id} (${row.subdomain})` },
  });
  revalidatePath("/admin/free-minecraft");
  return { ok: true };
}

export type FreemcCapacityContainer = {
  containerName: string;
  cpus: number;
  ramMb: number;
  /** ISO timestamp, `docker inspect .State.StartedAt` — empty if unavailable. */
  startedAt: string;
  ownerId: string | null;
  ownerName: string | null;
  ownerEmail: string | null;
  gameType: string;
  gameTypeLabel: string;
};

export type FreemcCapacitySnapshot = {
  totalCpus: number;
  totalRamMb: number;
  committedCpus: number;
  committedRamMb: number;
  reservedCpus: number;
  reservedRamMb: number;
  containers: FreemcCapacityContainer[];
};

/**
 * Live host-level capacity snapshot for the admin resource-usage view — see
 * lib/freemc-capacity.ts for the accounting (nproc/free -m for host totals,
 * `docker inspect` per running mc-free-* container for what's actually
 * assigned) and lib/free-minecraft-control.ts's recreateGameTypeContainer /
 * lib/actions-free-minecraft.ts's powerAction for where the same helper
 * GATES a customer-triggered start. This is read-only — it never starts,
 * stops, or otherwise touches a container, just reports what's already true.
 *
 * Resolves each running container's raw name back to its owning customer +
 * active game type via FreeMinecraftServer.containerName, so the admin view
 * shows something meaningful instead of a bare `mc-free-<userId>` string. A
 * container with no matching DB row (shouldn't normally happen, but SSH/DB
 * can disagree transiently) still shows up with null owner fields rather
 * than being silently dropped — an admin diagnosing a capacity problem needs
 * to see every running container, matched or not.
 */
export async function adminGetFreemcHostCapacity(): Promise<
  { ok: true; snapshot: FreemcCapacitySnapshot } | { ok: false; error: string }
> {
  await requireArea("fleet");

  try {
    const host = await freemcHost();
    const cap = await withServerSsh(host, (conn) => getFreemcHostCapacity(conn));

    const containerNames = cap.runningContainers.map((c) => c.containerName);
    const rows = containerNames.length
      ? await db.freeMinecraftServer.findMany({
          where: { containerName: { in: containerNames } },
          select: {
            containerName: true,
            activeGameType: true,
            userId: true,
            user: { select: { name: true, email: true } },
          },
        })
      : [];
    const byContainer = new Map(rows.map((r) => [r.containerName, r]));

    const containers: FreemcCapacityContainer[] = cap.runningContainers.map((c) => {
      const row = byContainer.get(c.containerName);
      return {
        containerName: c.containerName,
        cpus: c.cpus,
        ramMb: c.ramMb,
        startedAt: c.startedAt,
        ownerId: row?.userId ?? null,
        ownerName: row?.user.name ?? null,
        ownerEmail: row?.user.email ?? null,
        gameType: row?.activeGameType ?? "unknown",
        gameTypeLabel: (row ? FREEMC_GAME_TYPES[row.activeGameType]?.label : undefined) ?? row?.activeGameType ?? "Unknown",
      };
    });

    return {
      ok: true,
      snapshot: {
        totalCpus: cap.totalCpus,
        totalRamMb: cap.totalRamMb,
        committedCpus: cap.committedCpus,
        committedRamMb: cap.committedRamMb,
        reservedCpus: FREEMC_RESERVED_CPUS,
        reservedRamMb: FREEMC_RESERVED_RAM_MB,
        containers,
      },
    };
  } catch (e) {
    console.error("[admin-freemc] capacity check failed:", e);
    return { ok: false, error: "Could not reach the free Minecraft host." };

"use client";

import { useActionState, useEffect, useState, useTransition } from "react";
import {
  deleteFreeMinecraftServer,
  renameFreeMinecraftServer,
  changeFreeMinecraftSubdomain,
  sendFreeMinecraftCommand,
  getFreeMinecraftPlayers,
  applyFreeMinecraftSettings,
} from "@/lib/actions-free-minecraft";
import { PublicListingCard } from "./PublicListingCard";
import { InventoryEditor } from "./InventoryEditor";
import { ModsTab } from "./ModsTab";
import { RolesTab } from "./RolesTab";
import { OverviewRedesigned } from "./OverviewRedesigned";
import { SavedWorldsPanel } from "./SavedWorldsPanel";
import { FreeMcHero, FreeTierNote } from "./v2/FreeMcHero";
import { Icon } from "@/components/nx/Icon";
import type { FreeMcGameType } from "./GameTypeGrid";
import type { FreeMcGameMode } from "./GameModeSelector";

type Server = {
  id: string;
  subdomain: string;
  name: string | null;
  preset: string;
  activeGameType: string;
  activeGameMode: string;
  running: boolean;
  players: { online: number; max: number } | null;
  isPublic: boolean;
  publicTagline: string | null;
  publicDescription: string | null;
  extraMods: string[];
};

type Field = {
  key: string;
  label: string;
  group: string;
  type: "enum" | "bool" | "int" | "string";
  default: string | number | boolean;
  options?: { value: string; label: string }[];
  min?: number;
  max?: number;
  phase: "deploy" | "live";
  help?: string;
};

type Preset = {
  label: string;
  description: string;
  kind: "properties" | "plugins";
  properties: Record<string, string>;
  setupNote?: string;
  heroImage?: string;
};

/* The rail, on the paid panel's model (components/customer/gamepanel/v2).
   Same language, same interaction, a shorter list — because a free server
   genuinely has fewer things: no SFTP file manager, no scheduled tasks, no
   resource graph, no tier upgrade. Worlds gets its own entry here rather than
   sitting under Overview, since swapping worlds is the main thing people come
   back to a free server to do. */
const TABS: { key: string; label: string; icon: string }[] = [
  { key: "overview", label: "Overview", icon: "donut" },
  { key: "console",  label: "Console",  icon: "terminal" },
  { key: "worlds",   label: "Worlds",   icon: "archive" },
  { key: "mods",     label: "Mods",     icon: "cube" },
  { key: "players",  label: "Players",  icon: "users2" },
  { key: "roles",    label: "Roles",    icon: "shieldcheck" },
