function Console({ running }: { running: boolean }) {
  const [log, setLog] = useState<{ cmd: string; out: string; err?: boolean }[]>([]);
  const [pending, startTransition] = useTransition();

  function submit(formData: FormData) {
    const cmd = String(formData.get("command") ?? "");
    if (!cmd.trim()) return;
    startTransition(async () => {
      const res = await sendFreeMinecraftCommand({}, formData);
      setLog((l) => [...l, { cmd, out: res.error ?? res.response ?? "", err: !!res.error }]);
    });
  }

  return (
    <div className="card">
      <h3 className="font-semibold text-[var(--fg)]">Console</h3>
      {!running && (
        <p className="mt-1 text-sm text-amber-300">Server is asleep — commands won&apos;t reach it until someone connects.</p>
      )}
      <div className="nx-dark-island mt-3 h-64 overflow-y-auto rounded-lg border border-white/10 bg-[#05060f] p-3 font-mono text-xs">
        {log.length === 0 && <p className="text-slate-600">Command output will appear here.</p>}
        {log.map((l, i) => (
          <div key={i} className="mb-2">
            <p className="text-brand-300">&gt; {l.cmd}</p>
            <p className={l.err ? "text-red-400" : "text-slate-300"}>{l.out}</p>
          </div>
        ))}
      </div>
      <form action={submit} className="mt-3 flex gap-2">
        <input className="input flex-1 font-mono text-sm" name="command" placeholder="say hello" maxLength={512} autoComplete="off" />
        <button className="btn-primary text-sm" disabled={pending}>{pending ? "…" : "Send"}</button>
      </form>
    </div>
  );
}

function Players({ running }: { running: boolean }) {
  const [players, setPlayers] = useState<{ name: string }[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  function refresh() {
    startTransition(async () => {
      const res = await getFreeMinecraftPlayers();
      if (res.ok) { setPlayers(res.players); setError(null); }
      else { setError(res.error); setPlayers(null); }
    });
  }
  useEffect(() => { if (running) refresh(); }, [running]);

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-[var(--fg)]">Players online</h3>
        <button type="button" className="btn-ghost text-xs" onClick={refresh} disabled={pending}>
          {pending ? "Refreshing…" : "Refresh"}
