      </div>
      {!running ? (
        <p className="mt-3 text-sm text-slate-500">Server is asleep — nobody&apos;s connected.</p>
      ) : error ? (
        <p className="mt-3 text-sm text-red-400">{error}</p>
      ) : players && players.length === 0 ? (
        <p className="mt-3 text-sm text-slate-500">No one&apos;s online right now.</p>
      ) : players ? (
        <ul className="mt-3 space-y-1.5">
          {players.map((p) => (
            <li key={p.name} className="flex items-center gap-2 rounded-lg border border-white/[0.06] px-3 py-2 text-sm">
              <span className="h-2 w-2 rounded-full bg-emerald-400" /> {p.name}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

