/** Reads a `DeployIntent` back off the URL, using the exact keys
 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
 *  field has the query key it has. */
function parseIntent(sp: URLSearchParams): DeployIntent {
  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
  const num = (k: keyof DeployIntent) => {
    const v = raw(k);
    if (!v) return undefined;
    const n = Number(v);
    return Number.isFinite(n) ? n : undefined;
  };
  const serviceRaw = raw("service");
  const service: DeployService | undefined =
    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
      ? serviceRaw
      : undefined;
  const addonsRaw = raw("addons");
  return {
    service,
    planId: raw("planId") ?? undefined,
    termMonths: num("termMonths"),
    region: raw("region") ?? undefined,
    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
    diskGb: num("diskGb"),
    gameFamily: raw("gameFamily") ?? undefined,
    gamePlanId: raw("gamePlanId") ?? undefined,
    gameVariant: raw("gameVariant") ?? undefined,
    players: num("players"),
    hostingPlanId: raw("hostingPlanId") ?? undefined,
    emailPlanId: raw("emailPlanId") ?? undefined,
    couponCode: raw("couponCode") ?? undefined,
  };
}

/** The tier that best fits a desired headcount: the smallest slotted tier
 *  that still covers it, or — past the top of the ladder, or when the family
 *  has no slotted tiers at all — the single most expensive one, the closest
 *  real thing this family sells to "give me your biggest". Same judgment call
 *  GameLandingCombined's own player-count slider already makes, just applied
 *  against the LIVE catalogue instead of that page's illustrative fixture. */
function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
  if (tiers.length === 0) return null;
  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
  if (fits) return fits.id;
  const pool = slotted.length ? slotted : tiers;
  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
}

export type DeployService = "vps" | "game" | "hosting" | "email";

export type DeployIntent = {
  service?: DeployService;
  /** VPS plan id (Plan.id). */
  planId?: string;
  /** Shared across every product's term ladder (Order.termMonths). */
  termMonths?: number;
  region?: string;
  /** Subset of AddonOption["key"] — "backup" | "malware" | "docker" | "ip". */
  addons?: string[];
  /** Extra storage, VPS only. */
  diskGb?: number;
  gameFamily?: string;
  /** Exact GamePlan id, when the caller has one. */
  gamePlanId?: string;
  gameVariant?: string;
  /**
   * Desired concurrent-player count — used only when `gamePlanId` is absent,
   * to pick the nearest real tier for `gameFamily`. Ignored otherwise.
   */
  players?: number;
  hostingPlanId?: string;
  emailPlanId?: string;
  /** A checkout coupon to pre-fill, e.g. a marketing promo popup's own code. */
  couponCode?: string;
};

export const DEPLOY_PARAM: { [K in keyof Required<DeployIntent>]: string } = {
  service: "product",
  planId: "plan",
  termMonths: "term",
  region: "region",
  addons: "addons",
  diskGb: "disk",
  gameFamily: "family",
  gamePlanId: "tier",
  gameVariant: "variant",
  players: "players",
  hostingPlanId: "hosting",
  emailPlanId: "email",
  couponCode: "coupon",
};

export function deployHref(intent: DeployIntent): string {
  const qs = new URLSearchParams();
  for (const key of Object.keys(DEPLOY_PARAM) as (keyof DeployIntent)[]) {
    const value = intent[key];
    if (value === undefined || value === null || value === "") continue;
    if (Array.isArray(value)) {
      if (value.length === 0) continue;
      qs.set(DEPLOY_PARAM[key], value.join(","));
    } else {
      qs.set(DEPLOY_PARAM[key], String(value));
    }
  }
  const s = qs.toString();
  return s ? `/dashboard/deploy?${s}` : "/dashboard/deploy";
}

