  tps         Float?
  playersOnline Int?
  playersMax  Int?

  @@index([serverId, at])
  @@index([at])
}

/// Lifecycle/health events for a free server: CRASH (non-zero exit), OOM
/// (kernel OOM-killed — `oomKilled` true in docker inspect), WATCHDOG_RESTART,
/// BREAKER_OPEN, WAKE (mc-router wake with measured seconds), CAPACITY_REFUSED,
/// QUEUE_STARTED. `detail` is short plain text (exit code, seconds, ...).
model FreeMinecraftEvent {
  id       String              @id @default(cuid())
  serverId String
  server   FreeMinecraftServer @relation(fields: [serverId], references: [id], onDelete: Cascade)
  kind     String
  detail   String?
  // Numeric payload where one exists (wake seconds, exit code) — lets the
  // dashboard/upsell rules read real numbers without parsing `detail`.
  value    Float?
  at       DateTime            @default(now())

  @@index([serverId, at])
  @@index([kind, at])
}

/// Honest wait-list for the shared host: one row per server whose owner asked
/// to be started when a slot frees. The worker starts the OLDEST waiting row
/// once capacity allows (and only if it was requested in the last 20 minutes,
/// so nobody's server wakes long after they walked away). Position shown to
/// the player is a real COUNT of older WAITING rows.
model FreeMinecraftStartRequest {
  id          String              @id @default(cuid())
  serverId    String              @unique
  server      FreeMinecraftServer @relation(fields: [serverId], references: [id], onDelete: Cascade)
  status      String              @default("WAITING") // WAITING | STARTED | EXPIRED | CANCELLED
  requestedAt DateTime            @default(now())
  resolvedAt  DateTime?

  @@index([status, requestedAt])
}

/// Upgrade-prompt funnel for the free Minecraft dashboard (additive, read by
