/**
 * Pure sizing / JVM / capacity math for free-tier Minecraft containers.
 *
 * No I/O, no "use server" — imported by lib/free-minecraft-control.ts (the
 * `docker run` builder), lib/freemc-capacity.ts, the worker's health sweep and
 * the admin page, and unit-tested directly (test/freemc-limits.test.ts). Every
 * number here is either a measured incident (see the history notes) or a
 * documented upstream default, never a guess dressed up as a measurement.
 *
 * Investigation that produced this module (2026-10-01, freemc-host = node-2
 * vmid 100, 3 vCPU / 8 GB nominal):
 *  - All 4 OOM kills in the current boot (Sep 17 10:43, Sep 20 14:30, 15:44,
 *    19:26) were GLOBAL OOMs (`constraint=CONSTRAINT_NONE, global_oom`), not
 *    container-limit kills: the kernel's own report shows 1,636,846 of
 *    2,097,016 RAM pages "reserved" — the Proxmox balloon driver had shrunk the
 *    8 GB guest to ~1.8 GB usable (`balloon: 2048` floor in the VM config).
 *    Every one of those kills lands inside a window where node-2 sat above
 *    80% RAM (pvestatd's auto-ballooning threshold), per node-2's own RRD. One
 *    plugin server (1.5 GB RSS) plus mc-router was enough to exhaust it. The
 *    guest has also swapped in 86 GB over its 20-day uptime (balloon stats),
 *    which is what "very slow" feels like from inside a JVM. Fix is a VM
 *    config change (scripts/freemc/rollout/01-pin-guest-memory.sh) — no
 *    container limit can protect against the host taking the RAM away.
 *  - Vanilla containers run with `--cpus=1` and a 1536 MB limit. HotSpot's
 *    ergonomics treat <2 CPUs or <1792 MB as a non-server-class machine and
 *    pick SerialGC — a single-threaded, stop-the-world collector — unless a
 *    collector is named explicitly. Nothing named one (USE_AIKAR_FLAGS unset,
 *    no JVM_XX_OPTS), so every vanilla free server was running SerialGC. The
 *    "Can't keep up! Running 2000-3787ms behind" lines in the surviving logs
 *    all sit seconds after a player join (spawn-chunk load + GC on one core).
 *  - Plugin servers boot in 15-46 s warm, 30-77 s cold; mc-router wakes take
 *    23-33 s (median of 52 measured wakes since Sep 20). Neither is a bug, but
 *    both are what a player experiences as slow, and both are honest upsell
 *    signals when they get worse.
 */

export type FreemcEngine = "VANILLA" | "PAPER";
export type FreemcKind = "properties" | "plugins";

/** Memory floors (MB) per container kind — incident history lives at
 *  recreateGameTypeContainer's jvmRatio note in lib/free-minecraft-control.ts. */
export const FREEMC_VANILLA_RAM_FLOOR_MB = 1536;
export const FREEMC_PLUGINS_RAM_FLOOR_MB = 2560;
/** Heap share of the container limit. 0.7 left 461 MB of non-heap headroom at
 *  1536 MB, comfortably above both measured vanilla spikes (171/277 MB). */
export const FREEMC_JVM_HEAP_RATIO = 0.7;
/** Initial heap as a share of max heap. Lower than 1.0 so an idle/empty
 *  server's RSS stays well below its limit (G1 grows the heap on demand) —
 *  the itzg default (MEMORY sets Xms = Xmx) commits the whole heap at boot. */
export const FREEMC_INIT_HEAP_RATIO = 0.5;
/** Seconds `docker stop` (mc-router's idle scale-down included — it passes no
 *  timeout, so the container's own StopTimeout applies) waits for the world to
 *  save before SIGKILL. Docker's default is 10 s, short enough for a large
 *  world save to be cut off mid-write. */
export const FREEMC_STOP_TIMEOUT_S = 60;

export type ContainerResources = {
  /** Docker --memory and --memory-swap (no swap inside the container). */
  ramMb: number;
  /** -Xmx */
  heapMb: number;
  /** -Xms */
  initHeapMb: number;
  /** Docker --cpus (a CFS quota ceiling, not a reservation). */
  cpus: number;
};

export function containerResources(kind: FreemcKind, configuredRamMb: number): ContainerResources {
  const floor = kind === "plugins" ? FREEMC_PLUGINS_RAM_FLOOR_MB : FREEMC_VANILLA_RAM_FLOOR_MB;
  const configured = Number.isFinite(configuredRamMb) ? Math.round(configuredRamMb) : 0;
  const ramMb = Math.max(configured, floor);
  const heapMb = Math.max(256, Math.round(ramMb * FREEMC_JVM_HEAP_RATIO));
  const initHeapMb = Math.max(256, Math.min(heapMb, Math.round(heapMb * FREEMC_INIT_HEAP_RATIO)));
  const cpus = kind === "plugins" ? 2 : 1;
  return { ramMb, heapMb, initHeapMb, cpus };
}

/**
 * Explicit G1 tuning. This is Aikar's widely-used flag set for Minecraft
 * (the one itzg's USE_AIKAR_FLAGS applies) with ONE deliberate removal:
 * `-XX:+AlwaysPreTouch`, which commits the entire heap up front. On a shared
 * host where most servers are idle with one player, pre-touching every page
 * converts "heap the JVM might use" into "RAM the host has lost" the instant
 * the container wakes. Added: `+ExitOnOutOfMemoryError`, so a Java-heap OOM
 * ends the process cleanly (the watchdog records it as a crash) instead of
 * leaving a half-dead server players can connect to but not play on.
 */
export const FREEMC_JVM_XX_OPTS = [
  "-XX:+UseG1GC",
  "-XX:+ParallelRefProcEnabled",
  "-XX:MaxGCPauseMillis=200",
  "-XX:+UnlockExperimentalVMOptions",
  "-XX:+DisableExplicitGC",
  "-XX:G1NewSizePercent=30",
  "-XX:G1MaxNewSizePercent=40",
  "-XX:G1HeapRegionSize=8M",
  "-XX:G1ReservePercent=20",
  "-XX:G1HeapWastePercent=5",
  "-XX:G1MixedGCCountTarget=4",
  "-XX:InitiatingHeapOccupancyPercent=15",
  "-XX:G1MixedGCLiveThresholdPercent=90",
  "-XX:G1RSetUpdatingPauseTimePercent=5",
  "-XX:SurvivorRatio=32",
  "-XX:+PerfDisableSharedMem",
  "-XX:MaxTenuringThreshold=1",
  "-XX:+ExitOnOutOfMemoryError",
].join(" ");

/** itzg env vars that carry the JVM sizing + flags. MEMORY is deliberately
 *  NOT set: itzg's INIT_MEMORY/MAX_MEMORY take precedence over it. */
export function jvmEnv(res: ContainerResources): Record<string, string> {
  return {
    INIT_MEMORY: `${res.initHeapMb}m`,
    MAX_MEMORY: `${res.heapMb}m`,
    USE_AIKAR_FLAGS: "false",
    JVM_XX_OPTS: FREEMC_JVM_XX_OPTS,
  };
}

/**
 * Which server JAR a container boots. Plugin game types are always Paper (they
 * need the Bukkit API). The vanilla game type follows the server row's stored
 * engine — NULL means a row created before the engine column existed, which
 * keeps booting VANILLA so its world is never migrated to Paper's
 * split-dimension folder layout behind the owner's back.
 */
export function resolveEngine(kind: FreemcKind, stored: string | null | undefined): FreemcEngine {
  if (kind === "plugins") return "PAPER";
  return stored === "PAPER" ? "PAPER" : "VANILLA";
}

/** The engine a NEW server is created with, from the admin setting. */
export function defaultEngineFor(setting: string | null | undefined): FreemcEngine {
  return String(setting ?? "").toUpperCase() === "VANILLA" ? "VANILLA" : "PAPER";
}

/**
 * server.properties keys seeded into a brand-new server's /data BEFORE its
 * first boot. itzg only rewrites keys it has an env var for, so a seeded value
 * stays the player's to change in Settings afterwards (env-baking these would
 * silently reassert them on every restart — the same trap the game-mode keys
 * hit, see MODE_CONTROLLED_KEYS). Vanilla's defaults are view 10 / sim 10 /
 * 20 players; each step of view distance is a ring of chunks the server must
 * load, send and keep in RAM for every player.
 */
export const FREEMC_SEEDED_PROPERTIES: Record<string, string> = {
  "view-distance": "8",
  "simulation-distance": "6",
  "max-players": "10",
};

/** Renders FREEMC_SEEDED_PROPERTIES as a server.properties body. */
export function seededPropertiesBody(): string {
  return (
    "# Seeded by Nxeon at creation — change these any time in your dashboard's Settings tab.\n" +
    Object.entries(FREEMC_SEEDED_PROPERTIES)
      .map(([k, v]) => `${k}=${v}`)
      .join("\n") +
    "\n"
  );
}

// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

export type CapacitySnapshot = {
  totalCpus: number;
  totalRamMb: number;
  committedCpus: number;
  committedRamMb: number;
  runningCount: number;
};

export type CapacityBudget = {
  reservedCpus: number;
  reservedRamMb: number;
  /** `free_minecraft_max_concurrent` — a hard cap on awake containers. */
  maxConcurrent: number;
};

export type StartVerdict =
  | { ok: true }
  | { ok: false; reason: "COUNT" | "CPU" | "RAM" };

/** Would one more container with `add` resources fit? Order matters only for
 *  which reason is reported; every dimension must fit. */
export function evaluateStart(
  cap: CapacitySnapshot,
  add: { cpus: number; ramMb: number },
  budget: CapacityBudget,
): StartVerdict {
  if (cap.runningCount + 1 > budget.maxConcurrent) return { ok: false, reason: "COUNT" };
  const cpuBudget = cap.totalCpus - budget.reservedCpus;
  const ramBudget = cap.totalRamMb - budget.reservedRamMb;
  // Small epsilon: NanoCpus round-trips through 1e9 and can come back as
  // 1.9999999 for a container that was given exactly 2.
  if (cap.committedCpus + add.cpus > cpuBudget + 1e-6) return { ok: false, reason: "CPU" };
  if (cap.committedRamMb + add.ramMb > ramBudget) return { ok: false, reason: "RAM" };
  return { ok: true };
}

/** How many containers of one shape fit on an otherwise-empty host. */
export function slotsFor(
  host: { totalCpus: number; totalRamMb: number },
  per: { cpus: number; ramMb: number },
  budget: Omit<CapacityBudget, "maxConcurrent"> & { maxConcurrent?: number },
): number {
  const byCpu = Math.floor((host.totalCpus - budget.reservedCpus + 1e-6) / per.cpus);
  const byRam = Math.floor((host.totalRamMb - budget.reservedRamMb) / per.ramMb);
  const n = Math.max(0, Math.min(byCpu, byRam));
  return budget.maxConcurrent != null ? Math.min(n, budget.maxConcurrent) : n;
}

export type SizingRow = {
  label: string;
  cpus: number;
  ramMb: number;
  vanillaSlots: number;
  pluginSlots: number;
};

/** Sizing table for the admin page + docs: concurrent-awake capacity at the
 *  current per-container shapes, for the host as it is and a few sizes up. */
export function sizingTable(
  configuredRamMb: number,
  reserved: { reservedCpus: number; reservedRamMb: number },
  hosts: { label: string; cpus: number; ramMb: number }[],
): SizingRow[] {
  const v = containerResources("properties", configuredRamMb);
  const p = containerResources("plugins", configuredRamMb);
  return hosts.map((h) => ({
    label: h.label,
    cpus: h.cpus,
    ramMb: h.ramMb,
    vanillaSlots: slotsFor({ totalCpus: h.cpus, totalRamMb: h.ramMb }, v, reserved),
    pluginSlots: slotsFor({ totalCpus: h.cpus, totalRamMb: h.ramMb }, p, reserved),
  }));
}

/** Soft disk quota state. `null` diskMb (never measured) is never "over". */
export function diskQuotaState(diskMb: number | null | undefined, quotaMb: number): "ok" | "near" | "over" | "unknown" {
  if (diskMb == null || !Number.isFinite(diskMb)) return "unknown";
  if (!(quotaMb > 0)) return "ok";
  if (diskMb >= quotaMb) return "over";
  if (diskMb >= quotaMb * 0.8) return "near";
  return "ok";
}

