/**
 * Pure parsers + decision rules for the free-Minecraft health sweep
 * (worker/freemc-health.ts). No I/O — everything the sweep reads off the host
 * (docker inspect/stats, RCON replies, mc-router logs) is parsed here, so the
 * parsing is unit-tested (test/freemc-health.test.ts) instead of only ever
 * being exercised against the live host.
 */

export type DockerStatsReading = {
  name: string;
  cpuPct: number | null;
  memUsedMb: number | null;
  memLimitMb: number | null;
};

/** "123.4MiB" / "1.5GiB" / "980kB" / "2GB" -> MB (binary units for *iB). */
export function parseSizeToMb(s: string): number | null {
  const m = /^\s*([\d.]+)\s*([KMGT]?i?B)\s*$/i.exec(s);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  const unit = m[2].toUpperCase();
  const factor: Record<string, number> = {
    B: 1 / (1024 * 1024),
    KB: 1000 / (1024 * 1024),
    KIB: 1 / 1024,
    MB: 1_000_000 / (1024 * 1024),
    MIB: 1,
    GB: 1_000_000_000 / (1024 * 1024),
    GIB: 1024,
    TB: 1e12 / (1024 * 1024),
    TIB: 1024 * 1024,
  };
  const f = factor[unit];
  return f == null ? null : Math.round(n * f);
}

/** Parses one `docker stats --no-stream --format '{{.Name}}|{{.CPUPerc}}|{{.MemUsage}}'` line. */
export function parseDockerStatsLine(line: string): DockerStatsReading | null {
  const parts = line.trim().split("|");
  if (parts.length < 3 || !parts[0]) return null;
  const cpu = Number(parts[1].replace("%", "").trim());
  const [used, limit] = parts[2].split("/").map((s) => s.trim());
  return {
    name: parts[0].trim(),
    cpuPct: Number.isFinite(cpu) ? cpu : null,
    memUsedMb: used ? parseSizeToMb(used) : null,
    memLimitMb: limit ? parseSizeToMb(limit) : null,
