/** Strips Minecraft `§x` colour codes and ANSI escapes from RCON output. */
export function stripMcFormatting(s: string): string {
  return s.replace(/\u00a7[0-9a-fk-or]/gi, "").replace(/\x1b\[[0-9;]*m/g, "");
}

/**
 * Vanilla `/tick query` (MC 1.20.3+, also present on Paper). The reply's
 * translation key is commands.tick.query.rate.running —
 * "Target tick rate: 20.0 per second.\nAverage time per tick: 3.2ms (Target: 50.0ms)".
 * Returns the average mspt, or null if the line isn't there (older version,
 * sprinting/frozen state, or an error reply).
 */
export function parseTickQuery(text: string): number | null {
  const m = /Average time per tick:\s*([\d.]+)\s*ms/i.exec(stripMcFormatting(text));
  if (!m) return null;
  const v = Number(m[1]);
  return Number.isFinite(v) && v >= 0 ? v : null;
}

/** Paper `/tps`: "TPS from last 1m, 5m, 15m: 20.0, 19.98, 20.0" (a leading
 *  `*` marks values capped above 20). Returns the 1-minute figure. */
export function parsePaperTps(text: string): number | null {
  const m = /TPS from last 1m, 5m, 15m:\s*\*?([\d.]+)/i.exec(stripMcFormatting(text));
  if (!m) return null;
  const v = Number(m[1]);
  return Number.isFinite(v) && v >= 0 ? Math.min(20, v) : null;
}

/** TPS implied by an average tick time: a tick under 50ms still runs at 20. */
export function tpsFromMspt(mspt: number | null): number | null {
  if (mspt == null || !(mspt >= 0)) return null;
  if (mspt <= 50) return 20;
  return Math.round((1000 / mspt) * 100) / 100;
}

export type ExitClass = "CLEAN" | "OOM" | "KILLED" | "CRASH";

/**
 * Classifies a stopped container's last exit. 0 and 143 (SIGTERM — `docker
 * stop`, mc-router's idle scale-down) are clean. OOMKilled wins over the exit
 * code (a global-OOM kill of the JVM shows up as exit 255 or 137 with
 * OOMKilled=true — both seen live). 137 without OOMKilled is a SIGKILL: a
 * `docker stop` that outlived the stop timeout, or `docker rm -f`.
 */
export function classifyExit(exitCode: number, oomKilled: boolean): ExitClass {
  if (oomKilled) return "OOM";
  if (exitCode === 0 || exitCode === 143) return "CLEAN";
  if (exitCode === 137) return "KILLED";
  return "CRASH";
}

