 *  `docker inspect -f '{{.Name}}|{{.State.Running}}|{{.State.ExitCode}}|{{.State.OOMKilled}}|{{.State.StartedAt}}|{{.State.FinishedAt}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}'`. */
export function parseInspectLine(line: string): InspectRow | null {
  const p = line.trim().split("|");
  if (p.length < 6 || !p[0]) return null;
  const code = Number.parseInt(p[2], 10);
  return {
    name: p[0].replace(/^\//, ""),
    running: p[1] === "true",
    exitCode: Number.isFinite(code) ? code : 0,
    oomKilled: p[3] === "true",
    startedAt: p[4] ?? "",
    finishedAt: p[5] ?? "",
    health: (p[6] ?? "").trim(),
  };
