// Watchdog: restart backoff + crash-loop breaker
// ---------------------------------------------------------------------------

export const WATCHDOG_WINDOW_MS = 30 * 60_000;
/** Crashes (OOM/CRASH, not clean stops) inside the window that open the breaker. */
export const WATCHDOG_BREAKER_THRESHOLD = 3;
export const WATCHDOG_BREAKER_MS = 30 * 60_000;
/** Delay before an automatic restart, by how many crashes are already in the
 *  window INCLUDING this one: 1st -> next sweep, 2nd -> 5 minutes. */
export const WATCHDOG_BACKOFF_MS = [0, 5 * 60_000];

export type WatchdogDecision =
  | { action: "NONE"; why: string }
  | { action: "RESTART"; notBefore: Date }
  | { action: "OPEN_BREAKER"; until: Date };

export function decideAfterCrash(input: {
  now: Date;
  /** Times of crash/OOM events in the window, including the one just seen. */
  recentCrashTimes: Date[];
  breakerUntil: Date | null;
  autoRestartEnabled: boolean;
  /** Were players connected in the last sample before the crash? Restarting
   *  an empty crashed server just burns a capacity slot — mc-router wakes it
   *  again the moment someone connects. */
  hadPlayers: boolean;
}): WatchdogDecision {
  const { now } = input;
  if (input.breakerUntil && input.breakerUntil > now) return { action: "NONE", why: "breaker open" };
  const inWindow = input.recentCrashTimes.filter((t) => now.getTime() - t.getTime() <= WATCHDOG_WINDOW_MS);
  if (inWindow.length >= WATCHDOG_BREAKER_THRESHOLD) {
    return { action: "OPEN_BREAKER", until: new Date(now.getTime() + WATCHDOG_BREAKER_MS) };
  }
  if (!input.autoRestartEnabled) return { action: "NONE", why: "auto-restart disabled" };
  if (!input.hadPlayers) return { action: "NONE", why: "nobody was connected" };
  const latest = inWindow.reduce((a, t) => (t > a ? t : a), new Date(0));
  const delay = WATCHDOG_BACKOFF_MS[Math.min(inWindow.length, WATCHDOG_BACKOFF_MS.length) - 1] ?? 0;
  return { action: "RESTART", notBefore: new Date(latest.getTime() + delay) };
}

// ---------------------------------------------------------------------------
// mc-router wake latency
// ---------------------------------------------------------------------------

export type WakeMeasurement = { address: string; seconds: number; at: Date };

/**
 * Pairs mc-router's "Scaling up backend server" with the next "Woke up backend
 * server" for the same serverAddress and returns the measured gap. A scale-up
 * with no matching wake in `maxGapS` is a failed wake and is returned with
 * seconds = Infinity so the caller can count it separately.
 */
export function parseRouterWakes(log: string, maxGapS = 300): WakeMeasurement[] {
  const pending = new Map<string, Date>();
  const out: WakeMeasurement[] = [];
  for (const line of log.split("\n")) {
    const t = /time="([^"]+)"/.exec(line)?.[1];
    const addr = /serverAddress=(\S+)/.exec(line)?.[1];
    if (!t || !addr) continue;
    const at = new Date(t);
    if (Number.isNaN(at.getTime())) continue;
    if (line.includes("Scaling up backend server")) {
      const prev = pending.get(addr);
      if (prev && (at.getTime() - prev.getTime()) / 1000 > maxGapS) {
        out.push({ address: addr, seconds: Infinity, at: prev });
        pending.set(addr, at);
      } else if (!prev) {
        pending.set(addr, at);
      }
    } else if (line.includes("Woke up backend server")) {
      const start = pending.get(addr);
      if (!start) continue;
      pending.delete(addr);
      out.push({ address: addr, seconds: Math.round((at.getTime() - start.getTime()) / 1000), at: start });
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Sample summaries (dashboard + upsell evidence)
// ---------------------------------------------------------------------------

export type SampleLike = {
  at: Date;
  memUsedMb: number | null;
  memLimitMb: number | null;
  tps: number | null;
  mspt: number | null;
  playersOnline: number | null;
  playersMax: number | null;
};

export type SampleSummary = {
  count: number;
  lastAt: Date | null;
  memPeakPct: number | null;
  memLatestMb: number | null;
  memLimitMb: number | null;
  tpsMedian: number | null;
  tpsMin: number | null;
  msptMedian: number | null;
};

function median(xs: number[]): number | null {
  if (xs.length === 0) return null;
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

export function memPct(s: Pick<SampleLike, "memUsedMb" | "memLimitMb">): number | null {
  if (s.memUsedMb == null || !s.memLimitMb) return null;
  return (s.memUsedMb / s.memLimitMb) * 100;
}

export function summarizeSamples(samples: SampleLike[]): SampleSummary {
  const sorted = [...samples].sort((a, b) => a.at.getTime() - b.at.getTime());
  const last = sorted.at(-1) ?? null;
  const pcts = sorted.map(memPct).filter((x): x is number => x != null);
  const tps = sorted.map((s) => s.tps).filter((x): x is number => x != null);
  const mspt = sorted.map((s) => s.mspt).filter((x): x is number => x != null);
  return {
    count: sorted.length,
    lastAt: last?.at ?? null,
    memPeakPct: pcts.length ? Math.round(Math.max(...pcts)) : null,
    memLatestMb: last?.memUsedMb ?? null,
    memLimitMb: last?.memLimitMb ?? null,
    tpsMedian: tps.length ? Math.round(median(tps)! * 10) / 10 : null,
    tpsMin: tps.length ? Math.min(...tps) : null,
    msptMedian: mspt.length ? Math.round(median(mspt)! * 10) / 10 : null,
  };
}

