/**
 * When (and with what words) the free-Minecraft dashboard suggests a paid
 * server. Pure rules, unit-tested in test/freemc-upsell.test.ts.
 *
 * The contract, because this is the part that's easy to get wrong:
 *  - A prompt is only ever produced from a REAL signal the health sweep
 *    measured on THIS player's server (samples, crash events, wake timings,
 *    disk usage) or a real, fixed limit of the free tier the player just ran
 *    into (no Forge/Fabric). No signal -> no prompt. No countdowns, no
 *    "only N left", no invented percentages.
 *  - The evidence sentence quotes the measured numbers, so a player can see
 *    exactly why they're being shown it.
 *  - Dismissing hides every prompt for UPSELL_COOLDOWN_MS.
 *  - Copy never names or implies any outside infrastructure company — it's
 *    "a free node shared with other players" vs "your own server".
 */
import { memPct, type SampleLike } from "./freemc-health";

export const UPSELL_COOLDOWN_MS = 7 * 24 * 60 * 60_000;

/** Thresholds, named so the tests and the copy agree. */
export const UPSELL_MEM_PCT = 90;
export const UPSELL_MEM_MIN_HITS = 3;
export const UPSELL_TPS_LOW = 18;
export const UPSELL_TPS_MIN_HITS = 3;
export const UPSELL_WAKE_SLOW_S = 45;
export const UPSELL_WAKE_MIN_HITS = 2;
export const UPSELL_DISK_PCT = 80;

export type UpsellTrigger =
  | "CRASHES"
  | "MEMORY"
  | "LOW_TPS"
  | "PLAYER_CAP"
  | "DISK"
  | "WAKE_SLOW"
  | "MODDED";

export type UpsellEventLike = { kind: string; at: Date; value: number | null };

export type UpsellInput = {
  now: Date;
  /** Samples from the last 24 hours. */
  samples: SampleLike[];
  /** Events from the last 7 days. */
  events: UpsellEventLike[];
  diskMb: number | null;
  diskQuotaMb: number;
  /** When the player last dismissed a prompt (any trigger), if ever. */
  lastDismissedAt: Date | null;
  /** The tab the player is looking at — "mods" enables the MODDED context prompt. */
  context?: "overview" | "mods";
};

export type UpsellDecision = {
  trigger: UpsellTrigger;
  title: string;
  /** One sentence stating the measured evidence. */
  evidence: string;
};

const fmtGb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 === 0 ? 0 : 1)} GB`;

export function decideUpsell(input: UpsellInput): UpsellDecision | null {
  const { now } = input;
  if (input.lastDismissedAt && now.getTime() - input.lastDismissedAt.getTime() < UPSELL_COOLDOWN_MS) {
    return null;
  }
  const weekAgo = now.getTime() - 7 * 24 * 60 * 60_000;
  const dayAgo = now.getTime() - 24 * 60 * 60_000;
  const events = input.events.filter((e) => e.at.getTime() >= weekAgo);
  const samples = input.samples.filter((s) => s.at.getTime() >= dayAgo);

  // 1. Crashes — the strongest, most concrete signal.
  const ooms = events.filter((e) => e.kind === "OOM").length;
  const crashes = events.filter((e) => e.kind === "CRASH").length;
  if (ooms >= 1 || crashes >= 2) {
    const parts: string[] = [];
    if (ooms) parts.push(`${ooms} time${ooms === 1 ? "" : "s"} because it ran out of memory`);
    if (crashes) parts.push(`${crashes} time${crashes === 1 ? "" : "s"} for another reason`);
    return {
      trigger: "CRASHES",
      title: "Your server has stopped unexpectedly this week",
      evidence: `In the last 7 days your server stopped ${parts.join(" and ")}.`,
    };
  }

  // 2. Memory pressure — repeated, not a single spike.
  const memHits = samples.filter((s) => (memPct(s) ?? 0) >= UPSELL_MEM_PCT);
  if (memHits.length >= UPSELL_MEM_MIN_HITS) {
    const limit = memHits.find((s) => s.memLimitMb)?.memLimitMb ?? null;
    return {
      trigger: "MEMORY",
      title: "Your world is using nearly all of its memory",
      evidence: `Memory reached ${UPSELL_MEM_PCT}% or more of your ${limit ? fmtGb(limit) + " " : ""}limit in ${memHits.length} of the last ${samples.length} checks (past 24 hours).`,
    };
  }

  // 3. Low TPS while people were actually playing.
  const tpsHits = samples.filter((s) => (s.playersOnline ?? 0) > 0 && s.tps != null && s.tps < UPSELL_TPS_LOW);
  if (tpsHits.length >= UPSELL_TPS_MIN_HITS) {
    const worst = Math.min(...tpsHits.map((s) => s.tps as number));
    return {
      trigger: "LOW_TPS",
      title: "Your server is falling behind while people play",
      evidence: `Ticks per second dropped below ${UPSELL_TPS_LOW} (normal is 20) in ${tpsHits.length} checks with players online in the past 24 hours — the lowest was ${worst.toFixed(1)}.`,
    };
  }

  // 4. Player cap reached.
  const full = samples.find(
    (s) => s.playersOnline != null && s.playersMax != null && s.playersMax > 0 && s.playersOnline >= s.playersMax,
  );
  if (full) {
    return {
      trigger: "PLAYER_CAP",
      title: "Your server filled up",
      evidence: `All ${full.playersMax} player slots were in use on ${full.at.toUTCString().slice(0, 22)} UTC.`,
    };
  }

  // 5. Disk near the free quota.
  if (input.diskMb != null && input.diskQuotaMb > 0 && input.diskMb >= (input.diskQuotaMb * UPSELL_DISK_PCT) / 100) {
    return {
      trigger: "DISK",
      title: "Your worlds are close to the free storage limit",
      evidence: `Your worlds use ${input.diskMb} MB of the ${input.diskQuotaMb} MB free allowance.`,
    };
  }

  // 6. Slow wakes — measured, and only real sleeps (sub-2s "wakes" were already awake).
  const slow = events.filter((e) => e.kind === "WAKE" && e.value != null && e.value >= UPSELL_WAKE_SLOW_S);
  if (slow.length >= UPSELL_WAKE_MIN_HITS) {
    const longest = Math.max(...slow.map((e) => e.value as number));
    return {
      trigger: "WAKE_SLOW",
      title: "Waking your server is taking a while",
      evidence: `${slow.length} wake-ups this week took ${UPSELL_WAKE_SLOW_S} seconds or more (longest ${Math.round(longest)}s). Free servers sleep when empty; a paid server stays on.`,
    };
  }

  // 7. Context: the Mods tab, where the free tier's real limit is Paper plugins only.
  if (input.context === "mods") {
    return {
      trigger: "MODDED",
      title: "Want Forge or Fabric modpacks?",
      evidence: "Free servers run Paper plugins only — modpacks need more memory than a shared free node can give one world.",
    };
  }

  return null;
}

/** Whether a SHOWN event should be logged now (deduped to once per trigger per
 *  UTC day per user, so the funnel counts people, not page refreshes). */
export function shouldLogShown(trigger: UpsellTrigger, lastShown: { trigger: string; at: Date }[], now: Date): boolean {
  const day = now.toISOString().slice(0, 10);
  return !lastShown.some((e) => e.trigger === trigger && e.at.toISOString().slice(0, 10) === day);
}

/** Suggested paid tier for the trigger: the smallest plan with more RAM than
 *  the free container had, more slots than the cap they hit. Plans are the
 *  live GamePlan rows; returns the plan id or null. */
export function suggestPlan(
  plans: { id: string; ramMB: number; slots: number | null; priceCents: number }[],
  input: { freeRamMb: number | null; playersMax: number | null },
): string | null {
  const sorted = [...plans].sort((a, b) => a.priceCents - b.priceCents);
  const pick = sorted.find(
    (p) =>
      (input.freeRamMb == null || p.ramMB > input.freeRamMb) &&
      (input.playersMax == null || p.slots == null || p.slots > input.playersMax),
  );
  return (pick ?? sorted.at(-1))?.id ?? null;
}

