import { test } from "node:test";
import assert from "node:assert/strict";
import {
  containerResources,
  jvmEnv,
  resolveEngine,
  defaultEngineFor,
  evaluateStart,
  slotsFor,
  sizingTable,
  diskQuotaState,
  seededPropertiesBody,
  FREEMC_JVM_XX_OPTS,
} from "../lib/freemc-limits.ts";

test("vanilla floor + heap ratio match the incident-tested numbers", () => {
  const r = containerResources("properties", 1024);
  assert.deepEqual(r, { ramMb: 1536, heapMb: 1075, initHeapMb: 538, cpus: 1 });
});

test("plugins floor is 2560 MB / 2 cpus, configured value above the floor wins", () => {
  assert.deepEqual(containerResources("plugins", 1024), { ramMb: 2560, heapMb: 1792, initHeapMb: 896, cpus: 2 });
  assert.equal(containerResources("plugins", 4096).ramMb, 4096);
  assert.equal(containerResources("properties", Number.NaN).ramMb, 1536);
});

test("JVM env names G1 explicitly and never pre-touches the heap", () => {
  const env = jvmEnv(containerResources("properties", 1024));
  assert.equal(env.MAX_MEMORY, "1075m");
  assert.equal(env.INIT_MEMORY, "538m");
  assert.equal(env.USE_AIKAR_FLAGS, "false");
  assert.match(env.JVM_XX_OPTS, /-XX:\+UseG1GC/);
  assert.doesNotMatch(FREEMC_JVM_XX_OPTS, /AlwaysPreTouch/);
  // Must be shell-inert apart from spaces (it is shell-quoted, but keep it boring).
  assert.match(FREEMC_JVM_XX_OPTS, /^[A-Za-z0-9:+=\- ]+$/);
});

test("engine: plugins always Paper; legacy NULL vanilla rows stay vanilla", () => {
  assert.equal(resolveEngine("plugins", null), "PAPER");
  assert.equal(resolveEngine("plugins", "VANILLA"), "PAPER");
  assert.equal(resolveEngine("properties", null), "VANILLA");
  assert.equal(resolveEngine("properties", "PAPER"), "PAPER");
  assert.equal(defaultEngineFor(undefined), "PAPER");
  assert.equal(defaultEngineFor("vanilla"), "VANILLA");
});

test("evaluateStart reproduces the documented freemc-host ceilings", () => {
  const host = { totalCpus: 3, totalRamMb: 7941, committedCpus: 0, committedRamMb: 0, runningCount: 0 };
  const budget = { reservedCpus: 1, reservedRamMb: 1024, maxConcurrent: 8 };
  const v = containerResources("properties", 1024);
  const p = containerResources("plugins", 1024);
  assert.deepEqual(evaluateStart(host, p, budget), { ok: true });
  // one plugin server running -> no room for a vanilla one (2 + 1 > 2 cpus)
  const onePlugin = { ...host, committedCpus: 1.9999999, committedRamMb: 2560, runningCount: 1 };
  assert.deepEqual(evaluateStart(onePlugin, v, budget), { ok: false, reason: "CPU" });
  // two vanilla fit, a third does not
  const twoVanilla = { ...host, committedCpus: 2, committedRamMb: 3072, runningCount: 2 };
  assert.deepEqual(evaluateStart({ ...host, committedCpus: 1, committedRamMb: 1536, runningCount: 1 }, v, budget), { ok: true });
  assert.deepEqual(evaluateStart(twoVanilla, v, budget), { ok: false, reason: "CPU" });
  // count cap
  assert.deepEqual(evaluateStart({ ...host, runningCount: 8 }, v, budget), { ok: false, reason: "COUNT" });
  // a ballooned guest (1.8 GB visible) cannot take even one vanilla server
  assert.deepEqual(evaluateStart({ ...host, totalRamMb: 1800 }, v, budget), { ok: false, reason: "RAM" });
});

test("slotsFor / sizingTable", () => {
  const reserved = { reservedCpus: 1, reservedRamMb: 1024 };
  assert.equal(slotsFor({ totalCpus: 3, totalRamMb: 7941 }, { cpus: 1, ramMb: 1536 }, reserved), 2);
  assert.equal(slotsFor({ totalCpus: 3, totalRamMb: 7941 }, { cpus: 2, ramMb: 2560 }, reserved), 1);
  assert.equal(slotsFor({ totalCpus: 8, totalRamMb: 16384 }, { cpus: 1, ramMb: 1536 }, { ...reserved, maxConcurrent: 4 }), 4);
  const rows = sizingTable(1024, reserved, [
    { label: "now", cpus: 3, ramMb: 7941 },
    { label: "6c/16g", cpus: 6, ramMb: 16384 },
  ]);
  assert.deepEqual(rows.map((r) => [r.vanillaSlots, r.pluginSlots]), [[2, 1], [5, 2]]);
});

test("disk quota states", () => {
  assert.equal(diskQuotaState(null, 1024), "unknown");
  assert.equal(diskQuotaState(400, 1024), "ok");
  assert.equal(diskQuotaState(820, 1024), "near");
  assert.equal(diskQuotaState(1024, 1024), "over");
  assert.equal(diskQuotaState(5000, 0), "ok");
});

test("seeded server.properties body", () => {
  const body = seededPropertiesBody();
  assert.match(body, /^view-distance=8$/m);
  assert.match(body, /^simulation-distance=6$/m);
  assert.match(body, /^max-players=10$/m);
  assert.ok(!body.includes("'"), "body is piped through stdin, but keep it quote-free anyway");
});

