import { test } from "node:test";
import assert from "node:assert/strict";
import {
  parseSizeToMb,
  parseDockerStatsLine,
  parseTickQuery,
  parsePaperTps,
  tpsFromMspt,
  classifyExit,
  parseInspectLine,
  isZeroDockerTime,
  decideAfterCrash,
  parseRouterWakes,
  summarizeSamples,
} from "../lib/freemc-health.ts";

test("docker size units", () => {
  assert.equal(parseSizeToMb("812.3MiB"), 812);
  assert.equal(parseSizeToMb("1.5GiB"), 1536);
  assert.equal(parseSizeToMb("512KiB"), 1);
  assert.equal(parseSizeToMb("garbage"), null);
});

test("docker stats line", () => {
  assert.deepEqual(parseDockerStatsLine("mc-free-abc|12.50%|812.3MiB / 1.5GiB"), {
    name: "mc-free-abc",
    cpuPct: 12.5,
    memUsedMb: 812,
    memLimitMb: 1536,
  });
  assert.equal(parseDockerStatsLine(""), null);
  assert.equal(parseDockerStatsLine("x|--|--")?.cpuPct, null);
});

test("vanilla /tick query and Paper /tps", () => {
  const tick = "Target tick rate: 20.0 per second.\nAverage time per tick: 3.2ms (Target: 50.0ms)";
  assert.equal(parseTickQuery(tick), 3.2);
  assert.equal(parseTickQuery("Unknown or incomplete command"), null);
  assert.equal(parsePaperTps("§6TPS from last 1m, 5m, 15m: §a*20.0, §a19.98, §a20.0"), 20);
  assert.equal(parsePaperTps("TPS from last 1m, 5m, 15m: 14.2, 15.0, 18.0"), 14.2);
  assert.equal(tpsFromMspt(3.2), 20);
  assert.equal(tpsFromMspt(80), 12.5);
  assert.equal(tpsFromMspt(null), null);
