import { test } from "node:test";
import assert from "node:assert/strict";
import { decideUpsell, shouldLogShown, suggestPlan, UPSELL_COOLDOWN_MS, type UpsellInput } from "../lib/freemc-upsell.ts";

const now = new Date("2026-10-01T12:00:00Z");
const hoursAgo = (h: number) => new Date(now.getTime() - h * 3600_000);
const base: UpsellInput = { now, samples: [], events: [], diskMb: null, diskQuotaMb: 1024, lastDismissedAt: null };
const sample = (h: number, o: Partial<UpsellInput["samples"][number]> = {}) => ({
  at: hoursAgo(h),
  memUsedMb: 600,
  memLimitMb: 1536,
  tps: 20,
  mspt: 5,
  playersOnline: 1,
  playersMax: 10,
  ...o,
});

test("no signal -> no prompt (the default for a healthy server)", () => {
  assert.equal(decideUpsell(base), null);
  assert.equal(decideUpsell({ ...base, samples: [sample(1), sample(2), sample(3)] }), null);
});

test("a single OOM this week is enough; one plain crash is not", () => {
  const oom = decideUpsell({ ...base, events: [{ kind: "OOM", at: hoursAgo(30), value: null }] });
  assert.equal(oom?.trigger, "CRASHES");
  assert.match(oom!.evidence, /1 time because it ran out of memory/);
  assert.equal(decideUpsell({ ...base, events: [{ kind: "CRASH", at: hoursAgo(2), value: 1 }] }), null);
  assert.equal(decideUpsell({ ...base, events: [{ kind: "CRASH", at: hoursAgo(2), value: 1 }, { kind: "CRASH", at: hoursAgo(5), value: 1 }] })?.trigger, "CRASHES");
  // older than 7 days doesn't count
  assert.equal(decideUpsell({ ...base, events: [{ kind: "OOM", at: hoursAgo(24 * 8), value: null }] }), null);
});

test("memory needs 3 high samples in 24h, and quotes the real limit", () => {
  const hi = (h: number) => sample(h, { memUsedMb: 1450 });
  assert.equal(decideUpsell({ ...base, samples: [hi(1), hi(2), sample(3)] }), null);
  const d = decideUpsell({ ...base, samples: [hi(1), hi(2), hi(3), sample(4)] });
  assert.equal(d?.trigger, "MEMORY");
  assert.match(d!.evidence, /1\.5 GB limit in 3 of the last 4 checks/);
  // samples older than a day are ignored
  assert.equal(decideUpsell({ ...base, samples: [hi(25), hi(26), hi(27)] }), null);
});

test("low TPS only counts while players are online", () => {
  const lag = (h: number, players = 2) => sample(h, { tps: 14.5, playersOnline: players });
  assert.equal(decideUpsell({ ...base, samples: [lag(1, 0), lag(2, 0), lag(3, 0)] }), null);
  const d = decideUpsell({ ...base, samples: [lag(1), lag(2), lag(3)] });
  assert.equal(d?.trigger, "LOW_TPS");
  assert.match(d!.evidence, /lowest was 14\.5/);
});

test("player cap, disk, slow wakes, modded context", () => {
  assert.equal(decideUpsell({ ...base, samples: [sample(1, { playersOnline: 10, playersMax: 10 })] })?.trigger, "PLAYER_CAP");
  assert.equal(decideUpsell({ ...base, diskMb: 850 })?.trigger, "DISK");
  assert.equal(decideUpsell({ ...base, diskMb: 400 }), null);
  const wake = (s: number) => ({ kind: "WAKE", at: hoursAgo(3), value: s });
  assert.equal(decideUpsell({ ...base, events: [wake(28), wake(31), wake(46)] }), null);
  assert.equal(decideUpsell({ ...base, events: [wake(50), wake(61)] })?.trigger, "WAKE_SLOW");
  assert.equal(decideUpsell({ ...base, context: "mods" })?.trigger, "MODDED");
});

test("priority: crashes beat memory beat everything else", () => {
  const hi = (h: number) => sample(h, { memUsedMb: 1500 });
  const d = decideUpsell({ ...base, samples: [hi(1), hi(2), hi(3)], events: [{ kind: "OOM", at: hoursAgo(1), value: null }], diskMb: 1000 });
  assert.equal(d?.trigger, "CRASHES");
});

test("dismiss cooldown suppresses everything for 7 days", () => {
  const oomInput = { ...base, events: [{ kind: "OOM", at: hoursAgo(1), value: null }] };
  assert.equal(decideUpsell({ ...oomInput, lastDismissedAt: hoursAgo(24) }), null);
  assert.equal(decideUpsell({ ...oomInput, lastDismissedAt: new Date(now.getTime() - UPSELL_COOLDOWN_MS - 1) })?.trigger, "CRASHES");
});

test("copy never mentions an outside infrastructure company", () => {
  const inputs: UpsellInput[] = [
    { ...base, events: [{ kind: "OOM", at: hoursAgo(1), value: null }] },
    { ...base, samples: [1, 2, 3].map((h) => sample(h, { memUsedMb: 1500 })) },
    { ...base, samples: [1, 2, 3].map((h) => sample(h, { tps: 10 })) },
    { ...base, diskMb: 1000 },
    { ...base, events: [{ kind: "WAKE", at: hoursAgo(1), value: 60 }, { kind: "WAKE", at: hoursAgo(2), value: 70 }] },
    { ...base, context: "mods" },
  ];
  for (const i of inputs) {
    const d = decideUpsell(i)!;
    assert.ok(d, "each input fires");
    assert.doesNotMatch(`${d.title} ${d.evidence}`, /ovh|hetzner|provider|datacenter partner|aws|google cloud/i);
  }
});

test("SHOWN dedupe + plan suggestion", () => {
  assert.equal(shouldLogShown("MEMORY", [{ trigger: "MEMORY", at: hoursAgo(1) }], now), true === false ? true : false);
  assert.equal(shouldLogShown("MEMORY", [{ trigger: "MEMORY", at: hoursAgo(13) }], now), true);
  assert.equal(shouldLogShown("DISK", [{ trigger: "MEMORY", at: hoursAgo(1) }], now), true);
  const plans = [
    { id: "4g", ramMB: 4096, slots: 20, priceCents: 1294 },
    { id: "2g", ramMB: 2048, slots: 10, priceCents: 718 },
    { id: "8g", ramMB: 8192, slots: 50, priceCents: 2302 },
  ];
  assert.equal(suggestPlan(plans, { freeRamMb: 1536, playersMax: 8 }), "2g");
  assert.equal(suggestPlan(plans, { freeRamMb: 1536, playersMax: 10 }), "4g"); // must beat the cap they hit
  assert.equal(suggestPlan(plans, { freeRamMb: 2560, playersMax: null }), "4g");
  assert.equal(suggestPlan(plans, { freeRamMb: 9000, playersMax: null }), "8g");
  assert.equal(suggestPlan([], { freeRamMb: 1, playersMax: 1 }), null);
});

