import { exec, execInput, shellQuote } from "./ssh-exec";
import { getFreemcHostCapacity, FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB } from "./freemc-capacity";
import {
  containerResources,
  jvmEnv,
  resolveEngine,
  evaluateStart,
  seededPropertiesBody,
  FREEMC_STOP_TIMEOUT_S,
} from "./freemc-limits";
import { getSettingInt } from "./settings";

/** Root of every free server's data dir on freemc-host. */
export const FREEMC_SERVERS_ROOT = "/opt/freemc/servers";
/** Where destructive actions MOVE data instead of deleting it outright; the
 *  health sweep purges entries older than FREEMC_TRASH_DAYS. Same filesystem
 *  as the servers root, so the move is instant and costs no extra disk. */
export const FREEMC_TRASH_ROOT = "/opt/freemc/trash";
export const FREEMC_TRASH_DAYS = 7;

/** cuid-shaped ids only — every path built below goes through shellQuote too,
 *  this is belt-and-braces against a path ever escaping its server's dir. */
const SAFE_ID_RE = /^[a-z0-9]{10,40}$/;
const SAFE_FOLDER_RE = /^[a-z0-9_]{1,64}$/;

export function serverDataPath(serverId: string): string {
  if (!SAFE_ID_RE.test(serverId)) throw new Error("unsafe free server id");
  return `${FREEMC_SERVERS_ROOT}/${serverId}`;
}

/**
 * Moves a server's whole data dir (or one world folder inside it) to the
 * trash instead of `rm -rf` — a delete stays recoverable for
 * FREEMC_TRASH_DAYS. `touch` resets the mtime so the purge clock starts at the
 * delete, not at the world's last save. Missing source = no-op success.
 */
export async function moveToTrash(
  conn: Client,
  serverId: string,
  folder?: string,
): Promise<{ ok: boolean; error?: string }> {
  const base = serverDataPath(serverId);
  if (folder != null && !SAFE_FOLDER_RE.test(folder)) return { ok: false, error: "unsafe folder name" };
  const src = folder ? `${base}/${folder}` : base;
  const stamp = new Date().toISOString().replace(/[^0-9]/g, "").slice(0, 14);
  const dst = `${FREEMC_TRASH_ROOT}/${serverId}${folder ? `__${folder}` : ""}__${stamp}`;
  const r = await exec(
    conn,
    `if [ -e ${shellQuote(src)} ]; then mkdir -p ${shellQuote(FREEMC_TRASH_ROOT)} && mv ${shellQuote(src)} ${shellQuote(dst)} && touch ${shellQuote(dst)}; fi`,
    30_000,
  );
  if (r.code !== 0) return { ok: false, error: r.stderr.trim() || "move to trash failed" };
  return { ok: true };
}

/**
 * Removes only the plugin JARS (and Paper's remapped-jar cache) before a
 * recreate with a different plugin set — never the per-plugin data folders.
 *
 * Replaces `rm -rf /data/plugins/*` (type switch / legacy preset) and
 * `rm -rf <data>/plugins` (mod menu), which deleted every plugin's DATA along
 * with its jar: LuckPerms' H2 database (the Roles tab), IridiumSkyblock's
 * island database, Towny's towns/residents, Essentials homes/userdata and
 * Prison's mines. A SkyBlock -> Vanilla -> SkyBlock round trip, or simply
 * ticking one extra mod, silently reset all of it while the world folder
 * itself survived — "my island is gone but the world is still there". Runs on
 * the HOST path rather than `docker exec`, because the old `docker exec` form
 * silently did nothing whenever the container was asleep (the `.catch` hid
 * it), leaving the previous type's jars in place.
 */
export async function clearPluginJars(conn: Client, serverId: string): Promise<void> {
  const plugins = `${serverDataPath(serverId)}/plugins`;
  await exec(
    conn,
    `if [ -d ${shellQuote(plugins)} ]; then find ${shellQuote(plugins)} -maxdepth 1 -type f -name '*.jar' -delete; rm -rf ${shellQuote(`${plugins}/.paper-remapped`)}; fi`,
    20_000,
  );
}

/** Seeds view/simulation distance + player cap into a brand-new server's
 *  server.properties before its first boot (never overwrites an existing
 *  file) — see FREEMC_SEEDED_PROPERTIES for why these aren't env vars. */
export async function seedNewServerProperties(conn: Client, serverId: string): Promise<void> {
  const file = `${serverDataPath(serverId)}/server.properties`;
  await execInput(conn, `test -e ${shellQuote(file)} || cat > ${shellQuote(file)}`, seededPropertiesBody(), 10_000);
}

