    // Don't bother past this many days — the account is likely stale. Must
    // exceed the delay above (checked below) or the window is empty.
    { key: "dormant_winback_max_age_days", type: "int", min: 1, max: 365 },
  ],
  free_minecraft: [
    // Master switch — the customer-facing signup/landing page and dashboard flow
    // stay gated behind this even once code ships, same pattern as every other
    // new subsystem this platform has added. Defaults FALSE.
    { key: "free_minecraft_enabled", type: "bool" },
    // The public IP the wildcard DNS record and NAT/DNAT rule should point at —
    // the dedicated host VM this pool runs on (Server.hostname = "freemc-host").
    // Set once after provisioning; not auto-synced from the Server row.
    { key: "free_minecraft_public_ip", type: "string" },
    // Wildcard base domain players connect to: <subdomain>.<this>. A single
    // wildcard DNS A/AAAA record (*.<this> -> free_minecraft_public_ip) covers
    // every free server with zero per-server DNS work.
    { key: "free_minecraft_domain", type: "string" },
    // Per-container hard RAM cap, MB. This is a Docker --memory limit the
    // container physically cannot exceed (unlike a VM's soft ballooning target),
    // so it's the real ceiling on what one free server can consume.
    { key: "free_minecraft_ram_mb", type: "int", min: 256, max: 4096 },
    // World/data disk quota per free server, MB.
    { key: "free_minecraft_disk_mb", type: "int", min: 256, max: 8192 },
    // Idle auto-stop, MINUTES (mc-router's -auto-scale-down-after). A server
    // with nobody connected is stopped after this long, freeing its RAM back to
    // the pool — the mechanic that makes a shared host survivable.
    { key: "free_minecraft_idle_minutes", type: "int", min: 1, max: 180 },
    // Hard cap on how many free servers may be AWAKE (running) at once, across
    // every account — the circuit breaker protecting the host VM's own RAM
    // ceiling regardless of how many accounts have created a free server.
    { key: "free_minecraft_max_concurrent", type: "int", min: 1, max: 64 },
  ],
  email: [
    { key: "smtp_host", type: "string" },
    { key: "smtp_port", type: "int", min: 1, max: 65_535 },
    { key: "smtp_user", type: "string" },
        hint="A server with nobody connected stops after this long, freeing its RAM for someone else. Default 15."
      />
      <TextField
        label="Max concurrent awake servers"
        name="free_minecraft_max_concurrent"
        type="number"
        min={1}
        defaultValue={v.free_minecraft_max_concurrent}
        hint="Hard cap on how many free servers may be running at once across every account — protects the host VM regardless of signup volume. Default 8."
      />
    </SettingsForm>
  );
}

657:export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {

/** Keys whose stored value is a secret — never rendered back to the browser. */
export const SECRET_KEYS: readonly string[] = ["smtp_pass", "meta_capi_token", "kodely_partner_api_key", "kodely_webhook_secret", "discord_bot_token", "discord_client_secret"] as const;

/** True-ish coercion for values stored as "true"/"false"/"on"/"1". */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

/** Read one setting, falling back to an explicit default then SETTINGS_DEFAULTS. */
export async function getSetting(key: SettingKey | string, fallback?: string): Promise<string> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return row.value;
  return fallback ?? SETTINGS_DEFAULTS[key as SettingKey] ?? "";
}

/** Read one setting as a boolean. */
export async function getSettingBool(key: SettingKey | string, fallback = false): Promise<boolean> {
  const row = await db.setting.findUnique({ where: { key } });
  if (row) return isTrue(row.value);
  const def = SETTINGS_DEFAULTS[key as SettingKey];
