import {
  parseInspectLine,
  parseDockerStatsLine,
  parseTickQuery,
  parsePaperTps,
  tpsFromMspt,
  classifyExit,
  isZeroDockerTime,
  decideAfterCrash,
  parseRouterWakes,
  WATCHDOG_WINDOW_MS,
  type InspectRow,
} from "../lib/freemc-health";

const SWEEP_EVERY_MS = 2 * 60_000;
const DISK_EVERY_MS = 6 * 60 * 60_000;
const QUEUE_TTL_MS = 20 * 60_000;
const SAMPLE_RETENTION_MS = 14 * 24 * 60 * 60_000;
const EVENT_RETENTION_MS = 90 * 24 * 60 * 60_000;
/** A running container younger than this is still booting — skip RCON. */
const BOOT_GRACE_MS = 90_000;
/** At most this many RCON reads per sweep (each is ~1s over SSH). */
const MAX_RCON_PER_SWEEP = 8;

let inFlight = false;
let lastRun = 0;
let lastDisk = 0;
let lastRouterSince: Date | null = null;

/** Called from the worker loop every iteration; runs at most every 2 min. */
export function kickFreemcHealthSweep(): void {
  if (inFlight || Date.now() - lastRun < SWEEP_EVERY_MS) return;
  inFlight = true;
  lastRun = Date.now();
  freemcHealthSweep()
    .catch((e) => console.error("[freemc-health] sweep error", e))
    .finally(() => {
      inFlight = false;
    });
}

async function freemcHost() {
  return db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
}

export async function freemcHealthSweep(): Promise<void> {
  if (!(await getSettingBool("free_minecraft_enabled", false))) return;
  if (!(await getSettingBool("free_minecraft_health_enabled", true))) return;
  if (process.env.NXEON_SANDBOX === "1") return; // no real host behind a sandbox
  const host = await freemcHost();
  if (!host) return;

  const rows = await db.freeMinecraftServer.findMany({
    where: { status: "READY" },
    select: { id: true, userId: true, subdomain: true, containerName: true, engine: true, activeGameType: true, lastExitSeenAt: true, crashBreakerUntil: true },
  });
  const byContainer = new Map(rows.map((r) => [r.containerName, r]));
  const bySubdomain = new Map(rows.map((r) => [r.subdomain, r]));
  const autoRestart = await getSettingBool("free_minecraft_watchdog_autorestart", false);
  const maxConcurrent = await getSettingInt("free_minecraft_max_concurrent", 8);
  const domain = (await db.setting.findUnique({ where: { key: "free_minecraft_domain" } }))?.value ?? "play.nxeon.cloud";
  const now = new Date();

  await withServerSsh(host, async (conn) => {
    // ---- 1. inspect ----
    const fmt = "{{.Name}}|{{.State.Running}}|{{.State.ExitCode}}|{{.State.OOMKilled}}|{{.State.StartedAt}}|{{.State.FinishedAt}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}";
    const inspect = await exec(
      conn,
      `docker ps -a --filter ${shellQuote(`name=^/${FREEMC_CONTAINER_PREFIX}`)} --format '{{.Names}}' | xargs -r docker inspect -f ${shellQuote(fmt)}`,
      30_000,
    );
    const states: InspectRow[] = inspect.stdout
      .split("\n")
      .map(parseInspectLine)
      .filter((r): r is InspectRow => r != null && r.name.startsWith(FREEMC_CONTAINER_PREFIX));
    const running = states.filter((s) => s.running);

    // ---- 2. samples for running containers ----
    if (running.length) {
      const stats = await exec(
        conn,
        `docker stats --no-stream --format '{{.Name}}|{{.CPUPerc}}|{{.MemUsage}}' ${running.map((r) => shellQuote(r.name)).join(" ")}`,
        30_000,
      );
      const statByName = new Map(
        stats.stdout
          .split("\n")
          .map(parseDockerStatsLine)
          .filter((x): x is NonNullable<typeof x> => x != null)
          .map((x) => [x.name, x]),
      );
      let rconBudget = MAX_RCON_PER_SWEEP;
      for (const st of running) {
        const row = byContainer.get(st.name);
        if (!row) continue;
        const stat = statByName.get(st.name);
        let mspt: number | null = null;
        let tps: number | null = null;
        let playersOnline: number | null = null;
        let playersMax: number | null = null;
        const booting = now.getTime() - new Date(st.startedAt).getTime() < BOOT_GRACE_MS;
        if (!booting && rconBudget > 0) {
          rconBudget--;
          try {
            const status = await getFreeServerStatus(conn, st.name);
            playersOnline = status.players?.online ?? null;
            playersMax = status.players?.max ?? null;
            const paper = row.engine === "PAPER" || row.activeGameType !== "vanilla";
            if (paper) {
              const r = await sendRcon(conn, st.name, row.userId, "tps");
              if (r.ok) tps = parsePaperTps(r.response);
            }
            const q = await sendRcon(conn, st.name, row.userId, "tick query");
            if (q.ok) mspt = parseTickQuery(q.response);
            if (tps == null) tps = tpsFromMspt(mspt);
          } catch (e) {
            console.error("[freemc-health] rcon sample failed", st.name, e);
          }
        }
        await db.freeMinecraftSample.create({
          data: {
            serverId: row.id,
            at: now,
            memUsedMb: stat?.memUsedMb ?? null,
            memLimitMb: stat?.memLimitMb ?? null,
            cpuPct: stat?.cpuPct ?? null,
            mspt,
            tps,
            playersOnline,
            playersMax,
          },
        });

        // Hung: up past boot grace, docker's own healthcheck says unhealthy.
        if (!booting && st.health === "unhealthy") {
          const recent = await db.freeMinecraftEvent.findFirst({
            where: { serverId: row.id, kind: "HUNG", at: { gte: new Date(now.getTime() - 10 * 60_000) } },
          });
          if (!recent) {
            await db.freeMinecraftEvent.create({ data: { serverId: row.id, kind: "HUNG", detail: "docker healthcheck unhealthy" } });
          }
        }
      }
    }

    // ---- 3 + 4. exits, breaker, watchdog ----
    for (const st of states) {
      if (st.running || isZeroDockerTime(st.finishedAt)) continue;
      const row = byContainer.get(st.name);
      if (!row || row.lastExitSeenAt === st.finishedAt) continue;
      const finished = new Date(st.finishedAt);
      const fresh = now.getTime() - finished.getTime() < 24 * 60 * 60_000;
      const cls = classifyExit(st.exitCode, st.oomKilled);
      await db.freeMinecraftServer.update({ where: { id: row.id }, data: { lastExitSeenAt: st.finishedAt } });
      if (!fresh || cls === "CLEAN") continue;
      await db.freeMinecraftEvent.create({
        data: { serverId: row.id, kind: cls, detail: `exit ${st.exitCode}${st.oomKilled ? " (OOMKilled)" : ""}`, value: st.exitCode, at: finished },
      });
      if (cls === "KILLED") continue; // SIGKILL by docker itself — not a crash

      const crashTimes = (
        await db.freeMinecraftEvent.findMany({
          where: { serverId: row.id, kind: { in: ["OOM", "CRASH", "HUNG"] }, at: { gte: new Date(now.getTime() - WATCHDOG_WINDOW_MS) } },
          select: { at: true },
        })
      ).map((e) => e.at);
      const lastSample = await db.freeMinecraftSample.findFirst({
        where: { serverId: row.id, at: { lte: finished, gte: new Date(finished.getTime() - 10 * 60_000) } },
        orderBy: { at: "desc" },
        select: { playersOnline: true },
      });
      const decision = decideAfterCrash({
        now,
        recentCrashTimes: crashTimes,
        breakerUntil: row.crashBreakerUntil,
        autoRestartEnabled: autoRestart,
        hadPlayers: (lastSample?.playersOnline ?? 0) > 0,
      });
      if (decision.action === "OPEN_BREAKER") {
        await db.freeMinecraftServer.update({ where: { id: row.id }, data: { crashBreakerUntil: decision.until } });
        await db.freeMinecraftEvent.create({ data: { serverId: row.id, kind: "BREAKER_OPEN", detail: `${crashTimes.length} crashes in 30 min` } });
      } else if (decision.action === "RESTART" && decision.notBefore <= now) {
        // Backoff > 0 is honoured on a later sweep: the exit is bookmarked, so
        // the pending restart is re-derived below from the CRASH events.
        await tryStart(conn, row.id, st.name, maxConcurrent, "WATCHDOG_RESTART");
      }
    }

    // Deferred watchdog restarts (2nd crash: 5-minute backoff).
    if (autoRestart) {
      for (const st of states) {
        if (st.running) continue;
        const row = byContainer.get(st.name);
        if (!row || (row.crashBreakerUntil && row.crashBreakerUntil > now)) continue;
        const cls = classifyExit(st.exitCode, st.oomKilled);
        if (cls !== "OOM" && cls !== "CRASH") continue;
        const finished = new Date(st.finishedAt);
        if (now.getTime() - finished.getTime() > WATCHDOG_WINDOW_MS) continue;
        const already = await db.freeMinecraftEvent.findFirst({
          where: { serverId: row.id, kind: "WATCHDOG_RESTART", at: { gte: finished } },
        });
        if (already) continue;
        const crashTimes = (
          await db.freeMinecraftEvent.findMany({
            where: { serverId: row.id, kind: { in: ["OOM", "CRASH", "HUNG"] }, at: { gte: new Date(now.getTime() - WATCHDOG_WINDOW_MS) } },
            select: { at: true },
          })
        ).map((e) => e.at);
        const lastSample = await db.freeMinecraftSample.findFirst({
          where: { serverId: row.id, at: { lte: finished, gte: new Date(finished.getTime() - 10 * 60_000) } },
          orderBy: { at: "desc" },
          select: { playersOnline: true },
        });
        const d = decideAfterCrash({ now, recentCrashTimes: crashTimes, breakerUntil: row.crashBreakerUntil, autoRestartEnabled: true, hadPlayers: (lastSample?.playersOnline ?? 0) > 0 });
        if (d.action === "RESTART" && d.notBefore <= now) {
          await tryStart(conn, row.id, st.name, maxConcurrent, "WATCHDOG_RESTART");
        }
      }
    }

    // ---- 5. mc-router wake latency ----
    const since = lastRouterSince ?? new Date(now.getTime() - SWEEP_EVERY_MS - 60_000);
    const routerLog = await exec(
      conn,
      `docker logs mc-router --since ${shellQuote(since.toISOString())} 2>&1 | grep -E 'Scaling up backend server|Woke up backend server' | tail -n 500`,
      20_000,
    );
    lastRouterSince = now;
    for (const w of parseRouterWakes(routerLog.stdout)) {
      const sub = w.address.endsWith(`.${domain}`) ? w.address.slice(0, -(domain.length + 1)) : null;
      const row = sub ? bySubdomain.get(sub) : undefined;
      if (!row) continue;
      if (Number.isFinite(w.seconds) && w.seconds < 2) continue; // was already awake
      await db.freeMinecraftEvent.create({
        data: {
          serverId: row.id,
          kind: Number.isFinite(w.seconds) ? "WAKE" : "WAKE_FAILED",
          value: Number.isFinite(w.seconds) ? w.seconds : null,
          detail: Number.isFinite(w.seconds) ? `${w.seconds}s` : "no wake within 5 min",
          at: w.at,
        },
      });
    }

    // ---- 6. start queue ----
    await db.freeMinecraftStartRequest.updateMany({
      where: { status: "WAITING", requestedAt: { lt: new Date(now.getTime() - QUEUE_TTL_MS) } },
      data: { status: "EXPIRED", resolvedAt: now },
    });
    const next = await db.freeMinecraftStartRequest.findFirst({
      where: { status: "WAITING" },
      orderBy: { requestedAt: "asc" },
      include: { server: { select: { id: true, containerName: true, crashBreakerUntil: true } } },
    });
    if (next) {
      const st = states.find((s) => s.name === next.server.containerName);
      if (st?.running) {
        await db.freeMinecraftStartRequest.update({ where: { id: next.id }, data: { status: "STARTED", resolvedAt: now } });
      } else if (!(next.server.crashBreakerUntil && next.server.crashBreakerUntil > now)) {
        const started = await tryStart(conn, next.server.id, next.server.containerName, maxConcurrent, "QUEUE_STARTED");
        if (started) {
          await db.freeMinecraftStartRequest.update({ where: { id: next.id }, data: { status: "STARTED", resolvedAt: now } });
        }
      }
    }

    // ---- 7. disk + trash, every 6h ----
    if (Date.now() - lastDisk > DISK_EVERY_MS) {
      lastDisk = Date.now();
      const du = await exec(conn, `cd ${shellQuote(FREEMC_SERVERS_ROOT)} && du -sm -- * 2>/dev/null`, 120_000);
      const ids = new Set(rows.map((r) => r.id));
      for (const line of du.stdout.split("\n")) {
        const [mb, id] = line.trim().split(/\s+/);
        if (!id || !ids.has(id)) continue;
        const n = Number.parseInt(mb, 10);
        if (Number.isFinite(n)) await db.freeMinecraftServer.update({ where: { id }, data: { diskMb: n, diskCheckedAt: now } });
      }
      await exec(
        conn,
        `[ -d ${shellQuote(FREEMC_TRASH_ROOT)} ] && find ${shellQuote(FREEMC_TRASH_ROOT)} -mindepth 1 -maxdepth 1 -mtime +${FREEMC_TRASH_DAYS} -exec rm -rf {} + ; true`,
        120_000,
      );
    }
  });

  // ---- 8. retention ----
  await db.freeMinecraftSample.deleteMany({ where: { at: { lt: new Date(Date.now() - SAMPLE_RETENTION_MS) } } });
  await db.freeMinecraftEvent.deleteMany({ where: { at: { lt: new Date(Date.now() - EVENT_RETENTION_MS) } } });
}

/** `docker start` behind the same capacity rule every customer start uses. */
async function tryStart(
  conn: Parameters<Parameters<typeof withServerSsh>[1]>[0],
  serverId: string,
  containerName: string,
  maxConcurrent: number,
  kind: "WATCHDOG_RESTART" | "QUEUE_STARTED",
): Promise<boolean> {
  const assigned = await exec(conn, `docker inspect ${shellQuote(containerName)} --format '{{.HostConfig.NanoCpus}} {{.HostConfig.Memory}}'`, 10_000);
  if (assigned.code !== 0) return false;
  const [nano, mem] = assigned.stdout.trim().split(/\s+/);
  const cpus = (Number.parseInt(nano, 10) || 0) / 1e9;
  const ramMb = Math.round((Number.parseInt(mem, 10) || 0) / (1024 * 1024));
  const cap = await getFreemcHostCapacity(conn);
  const verdict = evaluateStart(
    { ...cap, runningCount: cap.runningContainers.length },
    { cpus, ramMb },
    { reservedCpus: FREEMC_RESERVED_CPUS, reservedRamMb: FREEMC_RESERVED_RAM_MB, maxConcurrent },
  );
  if (!verdict.ok) return false;
  const r = await exec(conn, `docker start ${shellQuote(containerName)}`, 30_000);
  if (r.code !== 0) return false;
  await db.freeMinecraftEvent.create({ data: { serverId, kind } });
  return true;
}

