"use server";

/**
 * Customer-facing reads/writes for free-Minecraft health, the start queue and
 * the upgrade prompt. All data comes from what worker/freemc-health.ts
 * measured on the caller's OWN server (FreeMinecraftSample/Event rows) and
 * the live GamePlan table — nothing is estimated here, and nothing here talks
 * to freemc-host (the dashboard stays fast even when the host is busy).
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, realUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { getSettingBool, getSettingInt } from "./settings";
import { summarizeSamples, type SampleSummary } from "./freemc-health";
import { decideUpsell, shouldLogShown, suggestPlan, type UpsellDecision, type UpsellTrigger } from "./freemc-upsell";
import { containerResources, diskQuotaState } from "./freemc-limits";
import { FREEMC_GAME_TYPES } from "./free-minecraft-control";
import { planIntroMonthlyCents } from "./intro-pricing";
import { deployHref } from "./deploy-intent";

export type UpgradePlan = {
  id: string;
  name: string;
  ramMb: number;
  cpuCores: number;
  diskGb: number;
  slots: number | null;
  priceCents: number;
  introPriceCents: number | null;
  href: string;
};

export type FreeMcHealth = {
  summary: SampleSummary;
  /** Last 24h samples, oldest first, for the sparkline. */
  series: { at: string; memPct: number | null; tps: number | null; players: number | null }[];
  crashes7d: number;
  ooms7d: number;
  lastWakeSeconds: number | null;
  disk: { mb: number | null; quotaMb: number; state: "ok" | "near" | "over" | "unknown"; checkedAt: string | null };
  freeShape: { ramMb: number; cpus: number };
  breakerUntil: string | null;
  queue: { status: "WAITING"; position: number; requestedAt: string } | null;
  upsell: (UpsellDecision & { suggestedPlanId: string | null }) | null;
  plans: UpgradePlan[];
};

async function myServer() {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  return { user, row };
}

/** True while an admin is impersonating — their views must not count in the funnel. */
async function impersonating(userId: string): Promise<boolean> {
  const real = await realUser().catch(() => null);
  return !!real && real.id !== userId;
}

async function upgradePlans(): Promise<UpgradePlan[]> {
  const plans = await db.gamePlan.findMany({
    where: { gameFamily: "minecraft", active: true, NOT: { name: { startsWith: "Custom" } } },
    orderBy: [{ priceCents: "asc" }],
    take: 4,
  });
  return plans.map((p) => ({
    id: p.id,
    name: p.name,
    ramMb: p.ramMB,
    cpuCores: p.cpuCores,
    diskGb: p.diskGB,
    slots: p.slots,
    priceCents: p.priceCents,
    introPriceCents: planIntroMonthlyCents(p),
    href: deployHref({ service: "game", gameFamily: "minecraft", gamePlanId: p.id }),
  }));
}

export async function getFreeMinecraftHealth(context: "overview" | "mods" = "overview"): Promise<FreeMcHealth | null> {
  const { user, row } = await myServer();
  if (!row) return null;
  const now = new Date();
  const dayAgo = new Date(now.getTime() - 24 * 60 * 60_000);
  const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60_000);

  const [samples, events, req, quotaMb, configuredRam, upsellOn, plans] = await Promise.all([
    db.freeMinecraftSample.findMany({ where: { serverId: row.id, at: { gte: dayAgo } }, orderBy: { at: "asc" }, take: 800 }),
    db.freeMinecraftEvent.findMany({ where: { serverId: row.id, at: { gte: weekAgo } }, orderBy: { at: "desc" }, take: 300 }),
    db.freeMinecraftStartRequest.findUnique({ where: { serverId: row.id } }),
    getSettingInt("free_minecraft_disk_mb", 1024),
    getSettingInt("free_minecraft_ram_mb", 1024),
    getSettingBool("free_minecraft_upsell_enabled", true),
    upgradePlans(),
  ]);

  const kind = FREEMC_GAME_TYPES[row.activeGameType]?.kind ?? "properties";
  const shape = containerResources(kind, configuredRam);
  const summary = summarizeSamples(samples);

  let queue: FreeMcHealth["queue"] = null;
  if (req?.status === "WAITING") {
    const ahead = await db.freeMinecraftStartRequest.count({ where: { status: "WAITING", requestedAt: { lt: req.requestedAt } } });
    queue = { status: "WAITING", position: ahead + 1, requestedAt: req.requestedAt.toISOString() };
  }

  let upsell: FreeMcHealth["upsell"] = null;
  if (upsellOn) {
    const lastDismiss = await db.freeMinecraftUpsellEvent.findFirst({
      where: { userId: user.id, action: "DISMISSED" },
      orderBy: { at: "desc" },
      select: { at: true },
    });
    const decision = decideUpsell({
      now,
      samples,
      events: events.map((e) => ({ kind: e.kind, at: e.at, value: e.value })),
      diskMb: row.diskMb,
      diskQuotaMb: quotaMb,
      lastDismissedAt: lastDismiss?.at ?? null,
      context,
    });
    if (decision) {
      const lastPlayersMax = [...samples].reverse().find((s) => s.playersMax != null)?.playersMax ?? null;
      upsell = {
        ...decision,
        suggestedPlanId: suggestPlan(
          plans.map((p) => ({ id: p.id, ramMB: p.ramMb, slots: p.slots, priceCents: p.priceCents })),
          { freeRamMb: shape.ramMb, playersMax: decision.trigger === "PLAYER_CAP" ? lastPlayersMax : null },
        ),
      };
      if (!(await impersonating(user.id))) {
        const todays = await db.freeMinecraftUpsellEvent.findMany({
          where: { userId: user.id, action: "SHOWN", at: { gte: new Date(now.getTime() - 26 * 60 * 60_000) } },
          select: { trigger: true, at: true },
        });
        if (shouldLogShown(decision.trigger, todays, now)) {
          await db.freeMinecraftUpsellEvent
            .create({ data: { userId: user.id, serverId: row.id, trigger: decision.trigger, action: "SHOWN" } })
            .catch(() => {});
        }
      }
    }
  }

  const wake = events.find((e) => e.kind === "WAKE" && e.value != null);
  return {
    summary,
    series: samples.map((s) => ({
      at: s.at.toISOString(),
      memPct: s.memUsedMb != null && s.memLimitMb ? Math.round((s.memUsedMb / s.memLimitMb) * 100) : null,
      tps: s.tps,
      players: s.playersOnline,
    })),
    crashes7d: events.filter((e) => e.kind === "CRASH" || e.kind === "OOM").length,
    ooms7d: events.filter((e) => e.kind === "OOM").length,
    lastWakeSeconds: wake?.value ?? null,
    disk: { mb: row.diskMb, quotaMb, state: diskQuotaState(row.diskMb, quotaMb), checkedAt: row.diskCheckedAt?.toISOString() ?? null },
    freeShape: { ramMb: shape.ramMb, cpus: shape.cpus },
    breakerUntil: row.crashBreakerUntil && row.crashBreakerUntil > now ? row.crashBreakerUntil.toISOString() : null,
    queue,
    upsell,
    plans,
  };
}

const TRIGGERS: UpsellTrigger[] = ["CRASHES", "MEMORY", "LOW_TPS", "PLAYER_CAP", "DISK", "WAKE_SLOW", "MODDED"];

/** CLICKED / DISMISSED from the upgrade card. Dismiss starts the 7-day cooldown. */
export async function logFreeMinecraftUpsell(action: "CLICKED" | "DISMISSED", trigger: string): Promise<{ ok: boolean }> {
  const { user, row } = await myServer();
  if (action !== "CLICKED" && action !== "DISMISSED") return { ok: false };
  if (!TRIGGERS.includes(trigger as UpsellTrigger)) return { ok: false };
  const rl = checkRateLimit(`freemc:upsell:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) return { ok: false };
  // An impersonating admin's dismiss would silence a real customer's prompt
  // for a week and skew the funnel — record nothing.
  if (await impersonating(user.id)) return { ok: true };
  await db.freeMinecraftUpsellEvent.create({ data: { userId: user.id, serverId: row?.id ?? null, trigger, action } });
  if (action === "DISMISSED") revalidatePath("/dashboard/free-minecraft");
  return { ok: true };
}

/** Join the start queue after a capacity refusal. Idempotent. */
export async function joinFreeMinecraftStartQueue(_prev: unknown, _formData: FormData): Promise<{ error?: string; position?: number }> {
  const { user, row } = await myServer();
  if (!row) return { error: "You don't have a free server." };
  const rl = checkRateLimit(`freemc:queue:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
  if (row.crashBreakerUntil && row.crashBreakerUntil > new Date()) {
    return { error: "Starts are paused for a few minutes after repeated crashes — try again shortly." };
  }
  const existing = await db.freeMinecraftStartRequest.findUnique({ where: { serverId: row.id } });
  const req =
    existing?.status === "WAITING"
      ? existing
      : await db.freeMinecraftStartRequest.upsert({
          where: { serverId: row.id },
          update: { status: "WAITING", requestedAt: new Date(), resolvedAt: null },
          create: { serverId: row.id },
        });
  const ahead = await db.freeMinecraftStartRequest.count({ where: { status: "WAITING", requestedAt: { lt: req.requestedAt } } });
  revalidatePath("/dashboard/free-minecraft");
  return { position: ahead + 1 };
