"use client";

import Link from "next/link";
import { useActionState, useRef, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  startFreeMinecraftServer,
  stopFreeMinecraftServer,
  restartFreeMinecraftServer,
} from "@/lib/actions-free-minecraft";

/**
 * The free server's identity band — the same shape as the paid game panel's
 * hero (components/customer/gamepanel/v2/GameHero.tsx), because it is the same
 * job: who this server is, how to reach it, and the power controls, pinned
 * above whichever tab you're on.
 *
 * WHAT IT DELIBERATELY DOES NOT COPY, and why. The paid hero carries CPU, RAM
 * and disk vitals with live sparklines, read from that VM's own Proxmox RRD. A
 * free server is a container on a SHARED node — it has no VM of its own, so
 * there is no RRD to read and no honest number to put in those slots. Drawing
 * four vitals here with three of them invented would be exactly the thing the
 * rest of this panel was cleaned up to stop.
 *
 * So the vitals band carries what IS true of a free server: whether it's awake,
 * who's on it, what it's running, and the sleep rule that governs it. The
 * "what you'd get on a paid server" line is the honest version of an upsell —
 * it names the difference rather than implying this one is broken.
 */

export type FreeMcHeroData = {
  name: string;
  subdomain: string;
  address: string;
  running: boolean;
  players: { online: number; max: number | null } | null;
  gameTypeLabel: string;
  gameModeLabel: string;
};

function Vital({ label, value, sub, tone, pct }: {
  label: string; value: string; sub?: string; tone?: string; pct?: number;
}) {
  return (
    <div className="flex min-w-[112px] flex-col gap-1">
      <span className="text-[9.5px] font-bold uppercase tracking-[0.16em] text-tx-faint">{label}</span>
      <span className="num text-[15px] font-bold leading-none text-white">{value}</span>
      {pct !== undefined && (
        <span className="mt-1 h-[5px] w-full overflow-hidden rounded-full bg-white/10">
          <span className="block h-full rounded-full transition-[width] duration-500"
                style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone ?? "#5fd0ff" }} />
        </span>
      )}
      {sub && <span className="text-[10.5px] leading-snug text-tx-faint">{sub}</span>}
    </div>
  );
}

export function FreeMcHero({ data }: { data: FreeMcHeroData }) {
  const [copied, setCopied] = useState(false);
  const copyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [, startAction, startPending] = useActionState(startFreeMinecraftServer, {});
  const [, stopAction, stopPending] = useActionState(stopFreeMinecraftServer, {});
  const [, restartAction, restartPending] = useActionState(restartFreeMinecraftServer, {});
  const busy = startPending || stopPending || restartPending;

  const copy = () => {
    void navigator.clipboard?.writeText(data.address);
    setCopied(true);
    if (copyTimer.current) clearTimeout(copyTimer.current);
    copyTimer.current = setTimeout(() => setCopied(false), 1600);
  };

  const online = data.players?.online ?? 0;
  const max = data.players?.max ?? null;

  return (
    <header className="nx-dark-island relative min-h-[176px] overflow-hidden rounded-[18px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.72),rgba(2,7,20,.92))]">
      {/* Minecraft's own key art, treated exactly as the paid hero treats it:
          full-bleed, centred, feathered at both edges so it belongs to the card
          rather than being a picture stuck to one side of it. */}
      <span aria-hidden className="pointer-events-none absolute inset-0">
        <span
          className="block h-full w-full"
          style={{
            WebkitMaskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
            maskImage: "linear-gradient(180deg, #000 0%, #000 58%, transparent 100%)",
          }}
        >
          {/* eslint-disable-next-line @next/next/no-img-element -- local key art, outside the optimizer */}
          <img
            src="/games/art/minecraft_hero.jpg"
            alt=""
            className="h-full w-full object-cover object-center opacity-40"
            style={{
              WebkitMaskImage: "linear-gradient(90deg, transparent 0%, #000 20%, #000 80%, transparent 100%)",
              maskImage: "linear-gradient(90deg, transparent 0%, #000 20%, #000 80%, transparent 100%)",
            }}
          />
        </span>
        <span className="absolute inset-0"
              style={{ background: "linear-gradient(180deg,rgba(2,7,20,.3) 0%,rgba(2,7,20,.55) 55%,rgba(2,7,20,.86) 100%)" }} />
      </span>

      <div className="relative flex flex-col gap-3.5 px-5 py-4">
        <div className="flex flex-wrap items-center gap-x-5 gap-y-3">
          <span className="grid h-[58px] w-[58px] flex-none place-items-center overflow-hidden rounded-[14px] border border-rim-hi bg-[#050d20] shadow-lg">
            {/* eslint-disable-next-line @next/next/no-img-element -- local cover art */}
            <img src="/games/art/minecraft_poster.jpg" alt="" className="h-full w-full object-cover" />
          </span>

          <div className="flex min-w-0 flex-col gap-1.5">
            <div className="flex flex-wrap items-center gap-2.5">
              <h1 className="truncate text-[26px] font-extrabold leading-none tracking-[-0.028em] text-white">
                {data.name || data.subdomain}
              </h1>
              <span className={
                "inline-flex flex-none items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-bold backdrop-blur " +
                (data.running
                  ? "border-emerald-400/40 bg-emerald-950/60 text-emerald-300"
                  : "border-slate-400/35 bg-slate-900/60 text-slate-300")
              }>
                <span className={"h-[6px] w-[6px] rounded-full " + (data.running ? "bg-emerald-400" : "bg-slate-400")} />
                {data.running ? "Awake" : "Asleep"}
              </span>
              <span className="rounded-[6px] border border-[#a86bff]/45 bg-[#a86bff]/12 px-2 py-0.5 text-[9.5px] font-bold uppercase tracking-wide text-[#c4a6ff]">
                Free
              </span>
            </div>
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-[12.5px] text-tx-dim">
              <span className="font-semibold text-white/85">Minecraft</span>
              <span className="text-rim-hi">|</span>
              <button type="button" onClick={copy} title={copied ? "Copied" : `Copy ${data.address}`}
                      className="group/c inline-flex items-center gap-1.5 font-mono text-[12px] transition hover:text-white">
                {data.address}
                <Icon name={copied ? "checkcircle" : "copy"} size={11} tone="inherit"
                      className={copied ? "text-emerald-400" : "opacity-50 transition-opacity group-hover/c:opacity-100"} />
              </button>
            </div>
          </div>

          <div className="ml-auto flex flex-none items-center gap-2">
            {!data.running ? (
              <form action={startAction}>
                <button disabled={busy}
                        className="inline-flex items-center gap-2 rounded-[11px] border border-[#2a55b5] bg-[rgba(24,48,110,.8)] px-3.5 py-2 text-[13px] font-semibold text-white backdrop-blur transition hover:border-brand-400 disabled:opacity-40">
                  <Icon name="bolt" size={14} tone="inherit" /> {startPending ? "Waking…" : "Wake up"}
                </button>
              </form>
"use client";

/**
