 * illustration (floating islands at sunset, hooded adventurer, glowing blade)
 * authored as SVG by scripts/gen-freemc-art.mjs — not a Minecraft asset.
 *
 * The image is baked with its own left-to-right and bottom fades so it dissolves
 * into the card instead of ending on a hard edge; `FreeMcTopCardHero` adds one
 * more scrim on top so the card's text stays legible at any card width.
 */
export const FREEMC_TOP_CARD_HERO = "/games/art/freemc-dashboard_hero.jpg";

/**
 * Drop this inside the top server card (which needs `relative overflow-hidden`)

