"use client";

/**
 * Two honest panels for the free-Minecraft dashboard:
 *
 *  - <PerformanceCard>: what the health sweep (worker/freemc-health.ts)
 *    actually measured on THIS server — memory vs its limit, ticks per
 *    second, crashes, the last wake-up time, world size vs the free allowance.
 *    Every tile says "not measured yet" rather than showing a made-up number.
 *
 *  - <UpgradeCard>: shown ONLY when lib/freemc-upsell.ts found a real signal
 *    (or on the Mods tab, the real Forge/Fabric limit). Quotes the evidence,
 *    compares against the live paid Minecraft plans from the database,
 *    deep-links into the deploy wizard prefilled for Minecraft, explains how
 *    the world comes along, and can be dismissed (7-day cooldown).
 */
import Link from "next/link";
import { useEffect, useRef, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Sparkline } from "@/components/ui/charts";
import { formatMoney } from "@/lib/currency";
import { logFreeMinecraftUpsell, type FreeMcHealth } from "@/lib/actions-freemc-health";

const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 === 0 ? 0 : 1)} GB`;

function Tile({ label, value, sub, tone }: { label: string; value: string; sub?: string; tone?: "ok" | "warn" | "bad" }) {
  const color = tone === "bad" ? "text-red-300" : tone === "warn" ? "text-amber-300" : "text-white";
  return (
    <div className="flex min-w-0 flex-col gap-1 rounded-[12px] border border-rim-soft bg-[rgba(3,9,24,.55)] px-3.5 py-3">
      <span className="text-[9.5px] font-bold uppercase tracking-[0.16em] text-tx-faint">{label}</span>
      <span className={`num text-[17px] font-bold leading-tight ${color}`}>{value}</span>
      {sub && <span className="text-[11px] leading-snug text-tx-dim">{sub}</span>}
    </div>
  );
}

export function PerformanceCard({ health }: { health: FreeMcHealth }) {
  const s = health.summary;
  const mem = health.series.map((p) => p.memPct).filter((v): v is number => v != null);
  const measured = s.count > 0;
  const memTone = s.memPeakPct == null ? undefined : s.memPeakPct >= 90 ? "bad" : s.memPeakPct >= 75 ? "warn" : "ok";
  const tpsTone = s.tpsMin == null ? undefined : s.tpsMin < 15 ? "bad" : s.tpsMin < 18 ? "warn" : "ok";
  const diskTone = health.disk.state === "over" ? "bad" : health.disk.state === "near" ? "warn" : "ok";

  return (
    <section className="card space-y-4" data-testid="freemc-performance">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h3 className="font-semibold text-[var(--fg)]">Performance</h3>
          <p className="text-xs text-tx-dim">
            Measured every 2 minutes while your server is awake. Last 24 hours unless noted.
          </p>
        </div>
        {mem.length > 1 && (
          <div className="flex items-center gap-2 text-[11px] text-tx-dim">
            memory <Sparkline data={mem} id="freemc-mem" width={110} height={30} stroke="#5fd0ff" />
          </div>
        )}
      </div>

      {!measured && (
        <p className="rounded-[10px] border border-rim-soft bg-well px-3 py-2 text-[12.5px] text-tx-dim">
          No measurements yet — they start the next time your server is awake.
        </p>
      )}

      <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-3 lg:grid-cols-5">
        <Tile
          label="Memory"
          value={s.memLatestMb != null && s.memLimitMb ? `${gb(s.memLatestMb)} / ${gb(s.memLimitMb)}` : "—"}
          sub={s.memPeakPct != null ? `peak ${s.memPeakPct}% of limit` : "not measured yet"}
          tone={memTone}
        />
        <Tile
          label="Ticks / second"
          value={s.tpsMedian != null ? s.tpsMedian.toFixed(1) : "—"}
          sub={s.tpsMin != null ? `lowest ${s.tpsMin.toFixed(1)} · 20 is full speed` : "not measured yet"}
          tone={tpsTone}
        />
        <Tile
          label="Crashes (7 days)"
          value={String(health.crashes7d)}
          sub={health.ooms7d ? `${health.ooms7d} out of memory` : health.crashes7d ? "unexpected stops" : "no unexpected stops"}
          tone={health.ooms7d ? "bad" : health.crashes7d ? "warn" : "ok"}
        />
        <Tile
          label="Last wake-up"
          value={health.lastWakeSeconds != null ? `${Math.round(health.lastWakeSeconds)}s` : "—"}
          sub={health.lastWakeSeconds != null ? "from first connect to ready" : "no wake measured this week"}
        />
        <Tile
          label="World storage"
          value={health.disk.mb != null ? `${health.disk.mb} MB` : "—"}
          sub={`of ${health.disk.quotaMb} MB free allowance`}
          tone={health.disk.mb != null ? diskTone : undefined}
        />
      </div>
      <p className="text-[11px] text-tx-faint">
        Your free server has a {gb(health.freeShape.ramMb)} memory limit and up to {health.freeShape.cpus} vCPU on a node
        shared with other free servers.
      </p>
    </section>
  );
}

export function UpgradeCard({
  health,
  exportHref,
  placement,
}: {
  health: FreeMcHealth;
  /** /api/free-minecraft/world-export?type=… for the active world. */
  exportHref: string;
  placement: "overview" | "mods";
}) {
  const decision = placement === "mods" ? health.modsUpsell : health.upsell;
  const [hidden, setHidden] = useState(false);
  const [, startTransition] = useTransition();
  const logged = useRef(false);

  useEffect(() => {
    if (!decision || logged.current) return;
    logged.current = true;
    void logFreeMinecraftUpsell("SHOWN", decision.trigger).catch(() => {});
  }, [decision]);

  if (!decision || hidden || health.plans.length === 0) return null;
  const suggested = health.plans.find((p) => p.id === decision.suggestedPlanId) ?? health.plans[0];

  const click = () => {
    void logFreeMinecraftUpsell("CLICKED", decision.trigger).catch(() => {});
  };
  const dismiss = () => {
    setHidden(true);
    startTransition(() => {
      void logFreeMinecraftUpsell("DISMISSED", decision.trigger).catch(() => {});
    });
  };

  return (
    <section
      data-testid="freemc-upgrade"
      className="relative overflow-hidden rounded-[16px] border border-[#7b3fef]/40 bg-[linear-gradient(135deg,rgba(59,107,232,.16),rgba(123,63,239,.14)_55%,rgba(2,7,20,.6))] p-4 sm:p-5"
    >
      <div className="flex flex-wrap items-start gap-3">
        <span className="grid h-9 w-9 flex-none place-items-center rounded-[10px] border border-[#7b3fef]/45 bg-[#7b3fef]/15">
          <Icon name="bolt" size={16} tone="inherit" className="text-[#c4a6ff]" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#c4a6ff]">Need more resources?</p>
          <h3 className="mt-0.5 text-[16px] font-bold text-white">{decision.title}</h3>
          <p className="mt-1 text-[13px] leading-relaxed text-tx-dim">{decision.evidence}</p>
          <p className="mt-1 text-[13px] leading-relaxed text-tx-dim">
            Upgrade to a paid Minecraft server with your own dedicated RAM and CPU instead of a share of a free node —
            it never sleeps, and adds SFTP, scheduled tasks and backups you control.
          </p>
        </div>
        <button
          type="button"
          onClick={dismiss}
          className="flex-none rounded-[9px] px-2 py-1 text-[12px] font-semibold text-tx-dim transition hover:bg-white/[0.06] hover:text-white"
        >
          Not now
        </button>
      </div>

      <div className="mt-4 overflow-x-auto">
        <table className="w-full min-w-[520px] border-separate border-spacing-0 text-left text-[12.5px]">
          <thead>
            <tr className="text-[10px] uppercase tracking-[0.12em] text-tx-faint">
              <th className="pb-2 pr-3 font-bold">Plan</th>
              <th className="pb-2 pr-3 font-bold">Memory</th>
              <th className="pb-2 pr-3 font-bold">vCPU</th>
              <th className="pb-2 pr-3 font-bold">Players</th>
              <th className="pb-2 pr-3 font-bold">Always on</th>
              <th className="pb-2 font-bold">Price</th>
            </tr>
          </thead>
          <tbody className="text-white/90">
            <tr className="text-tx-dim">
              <td className="border-t border-rim-soft py-2 pr-3">Your free server</td>
              <td className="border-t border-rim-soft py-2 pr-3">{gb(health.freeShape.ramMb)} limit, shared node</td>
              <td className="border-t border-rim-soft py-2 pr-3">up to {health.freeShape.cpus}, shared</td>
              <td className="border-t border-rim-soft py-2 pr-3">{health.summary.count ? "as configured" : "—"}</td>
              <td className="border-t border-rim-soft py-2 pr-3">sleeps when empty</td>
              <td className="border-t border-rim-soft py-2">Free</td>
            </tr>
            {health.plans.map((p) => (
              <tr key={p.id} className={p.id === suggested.id ? "bg-[#7b3fef]/10" : undefined}>
                <td className="border-t border-rim-soft py-2 pr-3 font-semibold">
                  {gb(p.ramMb)}
                  {p.id === suggested.id && (
                    <span className="ml-2 rounded-[5px] border border-[#5fd0ff]/40 px-1.5 py-0.5 text-[9.5px] font-bold uppercase text-[#5fd0ff]">
                      fits
                    </span>
                  )}
                </td>
                <td className="border-t border-rim-soft py-2 pr-3">{gb(p.ramMb)} dedicated</td>
                <td className="border-t border-rim-soft py-2 pr-3">{p.cpuCores} dedicated</td>
                <td className="border-t border-rim-soft py-2 pr-3">{p.slots ?? "—"}</td>
                <td className="border-t border-rim-soft py-2 pr-3">yes</td>
                <td className="border-t border-rim-soft py-2">
                  {p.introPriceCents != null ? (
                    <>
                      {formatMoney(p.introPriceCents)}/mo first term
                      <span className="block text-[11px] text-tx-faint">then {formatMoney(p.priceCents)}/mo</span>
                    </>
                  ) : (
                    <>{formatMoney(p.priceCents)}/mo</>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="mt-4 flex flex-wrap items-center gap-3">
        <Link
          href={suggested.href}
          onClick={click}
          className="inline-flex items-center gap-2 rounded-[11px] bg-[linear-gradient(120deg,#3b6be8,#7b3fef)] px-4 py-2 text-[13px] font-bold text-white shadow-[0_6px_24px_rgba(123,63,239,.35)] transition hover:brightness-110"
        >
          Upgrade to {gb(suggested.ramMb)} <Icon name="arrowright" size={13} tone="inherit" />
        </Link>
        <a
          href={exportHref}
          className="inline-flex items-center gap-2 rounded-[11px] border border-rim-hi px-3.5 py-2 text-[12.5px] font-semibold text-tx-dim transition hover:border-brand-400/50 hover:text-white"
        >
          <Icon name="download" size={13} tone="inherit" /> Download this world
        </a>
        <p className="min-w-[220px] flex-1 text-[11.5px] leading-snug text-tx-faint">
          Keep your world: download it (while your server is asleep), then upload the folder to your paid server with its
          file manager or SFTP.
        </p>
      </div>
    </section>
  );
}

