/**
 * GET /api/free-minecraft/world-export?type=<gameType>
 *
 * Streams one of the caller's OWN free-server worlds as a .tar.gz straight
 * off freemc-host (ssh -> tar stdout -> HTTP body, nothing buffered or stored
 * on the web box). The "keep your world" half of the upgrade path: the player
 * downloads it here and uploads the folder to their paid server's file
 * manager / SFTP. Automated free -> paid transfer is deliberately not built
 * (see DOCUMENTATION.md, free Minecraft stability — "keep your world").
 *
 * Safety:
 *  - only the caller's own server (looked up by session userId, never by a
 *    client-supplied id) and only a FREEMC_GAME_TYPES key — the folder list
 *    is built from that allowlisted key, every path is shell-quoted, and
 *    serverDataPath() refuses anything that isn't cuid-shaped;
 *  - refused while the server is awake: tarring a world mid-save produces a
 *    torn copy (region files written while being read). Asleep = consistent;
 *  - rate limited (an export reads hundreds of MB off the shared host's disk).
 */
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { withServerSsh, exec, shellQuote } from "@/lib/ssh-exec";
import { FREEMC_GAME_TYPES, serverDataPath } from "@/lib/free-minecraft-control";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

export async function GET(req: Request) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "Sign in first." }, { status: 401 });

  const url = new URL(req.url);
  const type = url.searchParams.get("type") ?? "";
  const gameType = FREEMC_GAME_TYPES[type];
  if (!gameType) return NextResponse.json({ error: "Unknown world." }, { status: 400 });

  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return NextResponse.json({ error: "You don't have a free server." }, { status: 404 });

  const rl = checkRateLimit(`freemc:export:${user.id}`, { max: 3, windowMs: 10 * 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many downloads — try again in ${rl.retryAfterSec}s.` }, { status: 429 });

  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!host) return NextResponse.json({ error: "Free servers are unavailable right now." }, { status: 503 });

  const base = serverDataPath(row.id);
  const folders = [type, `${type}_nether`, `${type}_the_end`, ...(gameType.extraWorldFolders ?? [])];

  // Pre-flight on its own connection so a refusal is a clean JSON error, not
  // a truncated download.
  let present: string[] = [];
  try {
    const pre = await withServerSsh(host, async (conn) => {
      const running = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`, 10_000);
      const awake = running.code === 0 && running.stdout.trim() === "true";
      const ls = await exec(
        conn,
        folders.map((f) => `[ -d ${shellQuote(`${base}/${f}`)} ] && echo ${shellQuote(f)}`).join("; ") + "; true",
        10_000,
      );
      return { awake, present: ls.stdout.split("\n").map((s) => s.trim()).filter((s) => folders.includes(s)) };
    });
    if (pre.awake) {
      return NextResponse.json(
        { error: "Your server is awake. Stop it (or wait until it falls asleep) so the world is fully saved, then download again." },
        { status: 409 },
      );
    }
    present = pre.present;
  } catch (e) {
    console.error("[freemc-export] preflight failed:", e);
    return NextResponse.json({ error: "Couldn't reach your server's storage — try again in a moment." }, { status: 502 });
  }
  if (present.length === 0) return NextResponse.json({ error: "That world hasn't been created yet." }, { status: 404 });

  const cmd = `tar -czf - -C ${shellQuote(base)} ${present.map(shellQuote).join(" ")}`;
  const body = new ReadableStream<Uint8Array>({
    start(controller) {
      withServerSsh(
        host,
        (conn) =>
          new Promise<void>((resolve, reject) => {
            conn.exec(cmd, (err, stream) => {
              if (err) return reject(err);
              stream.on("data", (chunk: Buffer) => controller.enqueue(new Uint8Array(chunk)));
              stream.stderr.on("data", (d: Buffer) => console.error("[freemc-export] tar:", d.toString().slice(0, 300)));
              stream.on("close", () => resolve());
              stream.on("error", reject);
            });
          }),
      )
        .then(() => controller.close())
        .catch((e) => {
          console.error("[freemc-export] stream failed:", e);
          controller.error(e);
        });
    },
  });

  const safeName = `${row.subdomain}-${type}-world.tar.gz`.replace(/[^a-z0-9._-]/gi, "_");
  return new NextResponse(body, {
    status: 200,
    headers: {
      "Content-Type": "application/gzip",
      "Content-Disposition": `attachment; filename="${safeName}"`,
      "Cache-Control": "no-store",
    },
  });
}

