import { db } from "@/lib/db";
import { getSettingInt } from "@/lib/settings";
import { Badge, StatCard, timeAgo } from "@/components/ui/primitives";
import { summarizeSamples } from "@/lib/freemc-health";
import { sizingTable } from "@/lib/freemc-limits";
import { FREEMC_RESERVED_CPUS, FREEMC_RESERVED_RAM_MB } from "@/lib/freemc-capacity";

/**
 * Admin observability for the free Minecraft tier — DB-only (what
 * worker/freemc-health.ts wrote), so it renders instantly and never adds SSH
 * load to freemc-host. Server component; rendered by app/admin/free-minecraft.
 */
export async function FreeMinecraftHealthPanels() {
  const now = Date.now();
  const dayAgo = new Date(now - 24 * 60 * 60_000);
  const weekAgo = new Date(now - 7 * 24 * 60 * 60_000);
  const monthAgo = new Date(now - 30 * 24 * 60 * 60_000);

  const [samples, events, recent, funnel, waiting, configuredRam, lastSample] = await Promise.all([
    db.freeMinecraftSample.findMany({
      where: { at: { gte: dayAgo } },
      orderBy: { at: "asc" },
      take: 20_000,
      select: { serverId: true, at: true, memUsedMb: true, memLimitMb: true, tps: true, mspt: true, playersOnline: true, playersMax: true },
    }),
    db.freeMinecraftEvent.groupBy({ by: ["serverId", "kind"], where: { at: { gte: weekAgo } }, _count: { _all: true }, _max: { value: true } }),
    db.freeMinecraftEvent.findMany({
      where: { at: { gte: weekAgo }, kind: { not: "WAKE" } },
      orderBy: { at: "desc" },
      take: 40,
      include: { server: { select: { subdomain: true } } },
    }),
    db.freeMinecraftUpsellEvent.groupBy({ by: ["trigger", "action"], where: { at: { gte: monthAgo } }, _count: { _all: true } }),
    db.freeMinecraftStartRequest.count({ where: { status: "WAITING" } }),
    getSettingInt("free_minecraft_ram_mb", 1024),
    db.freeMinecraftSample.findFirst({ orderBy: { at: "desc" }, select: { at: true } }),
  ]);
  const funnelUsers = await db.freeMinecraftUpsellEvent.groupBy({
    by: ["trigger", "action", "userId"],
    where: { at: { gte: monthAgo } },
  });

  const byServer = new Map<string, typeof samples>();
  for (const s of samples) {
    const list = byServer.get(s.serverId) ?? [];
    list.push(s);
    byServer.set(s.serverId, list);
  }
  const ids = [...new Set([...byServer.keys(), ...events.map((e) => e.serverId)])];
  const servers = ids.length
    ? await db.freeMinecraftServer.findMany({ where: { id: { in: ids } }, select: { id: true, subdomain: true, diskMb: true, crashBreakerUntil: true } })
    : [];
  const ev = (id: string, kind: string) => events.find((e) => e.serverId === id && e.kind === kind);

  const rows = servers
    .map((srv) => {
      const sum = summarizeSamples(byServer.get(srv.id) ?? []);
      return {
        ...srv,
        sum,
        ooms: ev(srv.id, "OOM")?._count._all ?? 0,
        crashes: ev(srv.id, "CRASH")?._count._all ?? 0,
        wakeMax: ev(srv.id, "WAKE")?._max.value ?? null,
      };
    })
    .sort((a, b) => b.ooms + b.crashes - (a.ooms + a.crashes) || (b.sum.memPeakPct ?? 0) - (a.sum.memPeakPct ?? 0));

  const totalOoms = events.filter((e) => e.kind === "OOM").reduce((n, e) => n + e._count._all, 0);
  const totalCrashes = events.filter((e) => e.kind === "CRASH").reduce((n, e) => n + e._count._all, 0);
  const triggers = [...new Set(funnel.map((f) => f.trigger))];
  const count = (t: string, a: string) => funnel.find((f) => f.trigger === t && f.action === a)?._count._all ?? 0;
  const users = (t: string, a: string) => funnelUsers.filter((f) => f.trigger === t && f.action === a).length;

  const sizing = sizingTable(configuredRam, { reservedCpus: FREEMC_RESERVED_CPUS, reservedRamMb: FREEMC_RESERVED_RAM_MB }, [
    { label: "freemc-host today (3 vCPU / 8 GB, when NOT ballooned)", cpus: 3, ramMb: 7941 },
    { label: "freemc-host while ballooned to its 2 GB floor", cpus: 3, ramMb: 1800 },
    { label: "Recommended: 6 vCPU / 16 GB, balloon off", cpus: 6, ramMb: 16_000 },
    { label: "8 vCPU / 24 GB, balloon off", cpus: 8, ramMb: 24_000 },
  ]);

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-4">
        <StatCard label="OOM kills (7d)" value={String(totalOoms)} />
        <StatCard label="Other crashes (7d)" value={String(totalCrashes)} />
        <StatCard label="Servers sampled (24h)" value={String(byServer.size)} />
        <StatCard label="Waiting for a slot" value={String(waiting)} />
      </div>
      <p className="text-xs text-slate-500">
        Health sweep: {lastSample ? `last sample ${timeAgo(lastSample.at)}` : "no samples yet (worker sweep not deployed, disabled, or nothing has been awake)"}.
      </p>

      <div>
        <h2 className="section-label mb-2">Server health (24h samples, 7d events)</h2>
        {rows.length === 0 ? (
          <div className="card p-4 text-sm text-slate-400">No measurements in the last 24 hours.</div>
        ) : (
          <div className="card overflow-x-auto p-0">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Server</th>
                  <th>Samples</th>
                  <th>RAM peak</th>
                  <th>TPS median / min</th>
                  <th>OOM / crash (7d)</th>
                  <th>Slowest wake</th>
                  <th>Disk</th>
                  <th>Breaker</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.id}>
                    <td className="font-mono text-xs">{r.subdomain}</td>
                    <td>{r.sum.count}</td>
                    <td>{r.sum.memPeakPct != null ? `${r.sum.memPeakPct}%` : "—"}</td>
                    <td>{r.sum.tpsMedian != null ? `${r.sum.tpsMedian} / ${r.sum.tpsMin?.toFixed(1)}` : "—"}</td>
                    <td>
                      {r.ooms ? <Badge tone="red">{r.ooms} OOM</Badge> : null} {r.crashes ? <Badge tone="amber">{r.crashes} crash</Badge> : null}
                      {!r.ooms && !r.crashes ? "—" : null}
                    </td>
                    <td>{r.wakeMax != null ? `${Math.round(r.wakeMax)}s` : "—"}</td>
                    <td>{r.diskMb != null ? `${r.diskMb} MB` : "—"}</td>
                    <td>{r.crashBreakerUntil && r.crashBreakerUntil.getTime() > now ? <Badge tone="red">open</Badge> : "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <div>
          <h2 className="section-label mb-2">Recent events (7d, wakes hidden)</h2>
          <div className="card max-h-80 overflow-y-auto p-0">
            {recent.length === 0 ? (
              <p className="p-4 text-sm text-slate-400">Nothing recorded.</p>
            ) : (
              <ul className="divide-y divide-white/5 text-xs">
                {recent.map((e) => (
                  <li key={e.id} className="flex items-center gap-3 px-4 py-2">
                    <Badge tone={e.kind === "OOM" || e.kind === "BREAKER_OPEN" ? "red" : e.kind === "CRASH" || e.kind === "HUNG" ? "amber" : "slate"}>{e.kind}</Badge>
                    <span className="font-mono">{e.server.subdomain}</span>
                    <span className="flex-1 truncate text-slate-400">{e.detail}</span>
                    <span className="text-slate-500">{timeAgo(e.at)}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>

        <div>
          <h2 className="section-label mb-2">Upgrade prompt funnel (30d)</h2>
          <div className="card overflow-x-auto p-0">
            {triggers.length === 0 ? (
              <p className="p-4 text-sm text-slate-400">No prompts shown yet — they only appear when a server&apos;s own measurements justify one.</p>
            ) : (
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Trigger</th>
                    <th>Shown (users)</th>
                    <th>Clicked (users)</th>
                    <th>Dismissed</th>
                    <th>Click rate</th>
                  </tr>
                </thead>
                <tbody>
                  {triggers.map((t) => {
                    const shownU = users(t, "SHOWN");
                    const clickU = users(t, "CLICKED");
                    return (
                      <tr key={t}>
                        <td>{t}</td>
                        <td>
                          {count(t, "SHOWN")} ({shownU})
                        </td>
                        <td>
                          {count(t, "CLICKED")} ({clickU})
                        </td>
                        <td>{count(t, "DISMISSED")}</td>
                        <td>{shownU ? `${Math.round((clickU / shownU) * 100)}%` : "—"}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Raw rows: <code>FreeMinecraftUpsellEvent</code> (SHOWN deduped per trigger per user per day).
          </p>
        </div>
      </div>

      <div>
        <h2 className="section-label mb-2">Host sizing — concurrent awake servers</h2>
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Host shape</th>
                <th>Vanilla (1 vCPU / 1.5 GB each)</th>
                <th>Plugin types (2 vCPU / 2.5 GB each)</th>
              </tr>
            </thead>
            <tbody>
              {sizing.map((r) => (
                <tr key={r.label}>
                  <td>{r.label}</td>
                  <td>{r.vanillaSlots}</td>
                  <td>{r.pluginSlots}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="mt-2 text-xs text-slate-500">
          After reserving {FREEMC_RESERVED_CPUS} vCPU + {FREEMC_RESERVED_RAM_MB} MB for the OS, Docker and mc-router. The
          ballooned row is why every OOM kill since Sep 11 happened: the guest is given back only ~1.8 GB whenever node-2
          crosses 80% RAM. See the free Minecraft stability rollout in the docs.
        </p>
      </div>
    </div>
  );
}

