/**
 * Free Minecraft stability rollout — STEP 3: give EXISTING containers the new
 * container settings (explicit G1 JVM flags, Xms < Xmx, --stop-timeout=60,
 * log rotation, --restart=no, engine label). Container env/flags are fixed at
 * `docker run` time, so an existing server only picks them up when it is
 * recreated; new servers and any type switch / mod change / address change get
 * them automatically after deploy. This script does the rest, safely.
 *
 * Follows the standing rule from the 2026-09-05 bulk-sweep incident
 * (DOCUMENTATION.md): check `docker ps` first, ONE container at a time, never
 * touch a running server, and put every recreated server straight back to
 * sleep (`docker stop`) once it has booted.
 *
 * World data is never touched: same bind-mounted /data, same LEVEL, same
 * game type/mode/mods. Legacy vanilla rows (engine NULL) stay TYPE=VANILLA.
 *
 *   npx tsx scripts/freemc/rollout/03-recreate-asleep.ts            # dry run: lists candidates
 *   npx tsx scripts/freemc/rollout/03-recreate-asleep.ts --apply --limit 3
 *
 * Run from /opt/nxeon AFTER this branch is deployed (needs the prod .env and
 * the new lib code). Owner-run only. Rollback for any one server = the next
 * recreate (type switch etc.) or re-running an older build's recreate; world
 * data is not affected either way.
 */
import { db } from "../../../lib/db";
import { getSetting, getSettingInt } from "../../../lib/settings";
import { withServerSsh, exec, shellQuote } from "../../../lib/ssh-exec";
import { recreateGameTypeContainer, FREEMC_GAME_TYPES, FREEMC_GAME_MODES, serverDataPath } from "../../../lib/free-minecraft-control";

const apply = process.argv.includes("--apply");
const limitArg = process.argv.indexOf("--limit");
const limit = limitArg > -1 ? Number(process.argv[limitArg + 1]) || 1 : 1;

async function main() {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshManagementKeyEnc: true, sshPort: true, dedicatedIp: { select: { address: true } }, node: { select: { publicIp: true } } },
  });
  if (!host) throw new Error("freemc-host not found");
  const rows = await db.freeMinecraftServer.findMany({ where: { status: "READY" }, orderBy: { createdAt: "asc" } });
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);

  await withServerSsh(host, async (conn) => {
    let done = 0;
    for (const row of rows) {
      if (done >= limit && apply) break;
      const st = await exec(conn, `docker inspect -f '{{.State.Running}}|{{index .Config.Labels "nxeon.freemc.engine"}}' ${shellQuote(row.containerName)}`, 10_000);
      const [running, label] = st.stdout.trim().split("|");
      if (st.code !== 0) { console.log(`skip ${row.subdomain}: no container`); continue; }
      if (running === "true") { console.log(`skip ${row.subdomain}: AWAKE (never touch a running server)`); continue; }
      if (label && label !== "<no value>") { console.log(`skip ${row.subdomain}: already on new settings (${label})`); continue; }
      if (!apply) { console.log(`would recreate ${row.subdomain} (${row.activeGameType}/${row.activeGameMode}) then stop it`); continue; }

      const typeKey = FREEMC_GAME_TYPES[row.activeGameType] ? row.activeGameType : "vanilla";
      const extraEnv = row.extraMods.length && FREEMC_GAME_TYPES[typeKey].kind === "plugins"
        ? { MODRINTH_PROJECTS: [...new Set([...(FREEMC_GAME_TYPES[typeKey].env?.MODRINTH_PROJECTS ?? "").split(",").filter(Boolean), ...row.extraMods])].join(",") }
        : undefined;
      console.log(`recreating ${row.subdomain} ...`);
      const r = await recreateGameTypeContainer(conn, {
        containerName: row.containerName,
        dataPath: serverDataPath(row.id),
        subdomain: row.subdomain,
        domain,
        ramMb,
        ownerId: row.userId,
        gameType: FREEMC_GAME_TYPES[typeKey],
        gameTypeKey: typeKey,
        gameMode: FREEMC_GAME_MODES[row.activeGameMode] ?? FREEMC_GAME_MODES.survival,
        extraEnv,
        engine: row.engine,
      });
      // Back to sleep regardless of outcome — it was asleep before we came.
      const stop = await exec(conn, `docker stop ${shellQuote(row.containerName)}`, 90_000);
      console.log(`  ${r.ok ? "ok" : "FAILED: " + r.error}; stopped=${stop.code === 0}`);
      if (!r.ok) { console.log("Stopping the run on first failure — investigate before continuing."); break; }
      done++;
    }
    if (!apply) console.log("DRY RUN — add --apply [--limit N] to recreate (one at a time).");
  });
  await db.$disconnect();
}

main().catch((e) => { console.error(e); process.exit(1); });

