// Seeds the THROWAWAY nxeon_agt_freemc DB for UI verification. Never run against prod.
import { createHash } from "node:crypto";
import { SignJWT } from "jose";
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();
const scenario = process.argv[2] ?? "pressure"; // pressure | healthy | empty

async function main() {
  if (!/nxeon_agt_freemc/.test(process.env.DATABASE_URL ?? "")) throw new Error("refusing: not the throwaway DB");
  for (const [key, value] of Object.entries({ free_minecraft_enabled: "true", free_minecraft_domain: "play.nxeon.cloud" })) {
    await db.setting.upsert({ where: { key }, update: { value }, create: { key, value } });
  }
  const plan = await db.plan.upsert({
    where: { slug: "agt-base" },
    update: {},
    create: { slug: "agt-base", name: "Base", cpuCores: 2, ramMB: 2048, diskGB: 20, priceCents: 500 },
  });
  const plans = [
    { id: "gp2", name: "Minecraft — 2 GB / 10 slots", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 10, priceCents: 718, introPriceCents: 499 },
    { id: "gp4", name: "Minecraft — 4 GB / 20 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1294, introPriceCents: 899 },
    { id: "gp8", name: "Minecraft — 8 GB / 50 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 50, priceCents: 2302, introPriceCents: 1599 },
  ];
  for (const p of plans) {
    await db.gamePlan.upsert({ where: { id: p.id }, update: {}, create: { ...p, gameFamily: "minecraft", basePlanId: plan.id } });
  }
  const email = "freemc-agent@example.test";
  await db.user.deleteMany({ where: { email } });
  const user = await db.user.create({ data: { email, passwordHash: "x", name: "Free MC Tester", emailVerified: new Date() } as never });
  const server = await db.freeMinecraftServer.create({
    data: {
      userId: user.id,
      subdomain: "agtworld",
      containerName: `mc-free-${user.id}`,
      status: "READY",
      name: "Agent World",
      activeGameType: "lifesteal",
      preset: "lifesteal",
      engine: "PAPER",
      diskMb: scenario === "pressure" ? 412 : 180,
      diskCheckedAt: new Date(),
    },
  });
  const now = Date.now();
  if (scenario !== "empty") {
    for (let i = 0; i < 30; i++) {
      const at = new Date(now - (30 - i) * 4 * 60_000);
      const hot = scenario === "pressure" && i > 20;
      await db.freeMinecraftSample.create({
        data: {
          serverId: server.id,
          at,
          memUsedMb: hot ? 2380 + i : 1100 + i * 10,
          memLimitMb: 2560,
          cpuPct: hot ? 160 : 35,
          mspt: hot ? 64 : 9,
          tps: hot ? 15.6 : 20,
          playersOnline: 2,
          playersMax: 10,
        },
      });
    }
    await db.freeMinecraftEvent.create({ data: { serverId: server.id, kind: "WAKE", value: 29, detail: "29s", at: new Date(now - 3 * 3600_000) } });
    if (scenario === "pressure") {
      await db.freeMinecraftEvent.create({ data: { serverId: server.id, kind: "OOM", value: 255, detail: "exit 255 (OOMKilled)", at: new Date(now - 26 * 3600_000) } });
    }
  }
  const token = await new SignJWT({ sub: user.id, sv: 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("2d")
    .sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId: user.id, tokenHash: createHash("sha256").update(token).digest("hex") } });
  console.log(JSON.stringify({ token, cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session", userId: user.id }));
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

