import { chromium } from "/opt/nxeon/node_modules/playwright/index.mjs";
import fs from "node:fs";
const S = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad";
const seed = JSON.parse(fs.readFileSync(`${S}/fmc-seed-out.txt`, "utf8").trim().split("\n").pop());
const base = "http://localhost:3111";
const tag = process.argv[2] ?? "pressure";
const browser = await chromium.launch();
const errors = [];
for (const [name, vp] of [["desktop", { width: 1440, height: 1000 }], ["mobile", { width: 390, height: 844 }]]) {
  for (const theme of ["dark", "light"]) {
    const ctx = await browser.newContext({ viewport: vp });
    await ctx.addCookies([{ name: seed.cookie, value: seed.token, domain: "localhost", path: "/" }]);
    const page = await ctx.newPage();
    page.on("pageerror", (e) => errors.push(`${name}/${theme}: ${e.message}`));
    page.on("console", (m) => { if (m.type() === "error") errors.push(`${name}/${theme} console: ${m.text().slice(0, 200)}`); });
    await page.goto(`${base}/dashboard/free-minecraft`, { waitUntil: "networkidle", timeout: 180_000 });
    if (theme === "light") {
      await page.evaluate(() => document.documentElement.setAttribute("data-theme", "light"));
      await page.waitForTimeout(300);
    }
    const up = await page.locator('[data-testid="freemc-upgrade"]').count();
    const perf = await page.locator('[data-testid="freemc-performance"]').count();
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    console.log(JSON.stringify({ name, theme, upgradeCard: up, perfCard: perf, horizontalOverflowPx: overflow }));
    await page.screenshot({ path: `${S}/fmc-${tag}-${name}-${theme}.png`, fullPage: true });
    if (name === "desktop" && theme === "dark") {
      await page.getByRole("button", { name: "Mods" }).click();
      await page.waitForTimeout(800);
      await page.screenshot({ path: `${S}/fmc-${tag}-mods.png`, fullPage: false });
      console.log(JSON.stringify({ modsUpgrade: await page.locator('[data-testid="freemc-upgrade"]').count() }));
    }
    await ctx.close();
  }
}
await browser.close();
console.log("ERRORS", JSON.stringify(errors));

